window.OGE_TASKS_BY_NUMBER.informatics = [{"num": "1", "shortTitle": "Объём текста", "part": "Часть 1", "title": "Задание № 1: Количественные параметры информационных объектов (I = K · i)", "fipiSpec": {"number": "№ 1", "score": "1 балл", "time": "3 мин", "difficulty": "Базовый", "docSource": "Кодификатор и открытый банк ФИПИ ОГЭ 2026/2027"}, "theory": "<h4>Формулы кодирования текста</h4>\n     <div class=\"task-formula-box\">\n       <div class=\"math-row\"><strong>I = K · i</strong> (Информационный объём = число символов × вес 1 символа)</div>\n       <div class=\"math-subtext\">• 1 байт = 8 бит; &nbsp; 1 Кбайт = 1024 байта; &nbsp; 1 Мбайт = 1024 Кбайта.<br>• Кодировка КОИ-8 / Windows-1251: 1 символ = 8 бит = 1 байт.<br>• Кодировка UTF-16 / Unicode: 1 символ = 16 бит = 2 байта; UTF-32 = 4 байта.</div>\n     </div>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Переведите разницу объёма в символы:</strong> Разделите изменение размера (в байтах) на вес одного символа (в байтах).</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 2</div><div class=\"task-step-desc\"><strong>Вычтите лишнюю запятую и пробел!:</strong> При удалении слова из списка всегда удаляются и ставшие лишними <strong>1 запятая + 1 пробел = 2 символа</strong>!</div></div></div>", "examples": "<div class=\"task-example-card\"><div class=\"task-example-badge\">ФИПИ</div><p><strong>Условие:</strong> В кодировке UTF-16 (16 бит/символ) из списка городов удалили одно название, а также ставшие лишними запятую и пробел. Размер уменьшился на 18 байт. Найдите удалённое слово.</p><div class=\"task-example-solution\"><strong>Решение:</strong><p>16 бит = 2 байта/символ. Всего удалено: 18 / 2 = 9 символов. Вычитаем запятую и пробел: 9 − 2 = 7 букв. Ищем город из 7 букв.</p><div class=\"task-answer-box\">Ответ: <strong>Город из 7 букв</strong></div></div></div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Пробелы и запятые</strong><p>Почти все ошибки в №1 — забыть вычесть 2 лишних символа (запятую и пробел)!</p></div>"}, {"num": "2", "shortTitle": "Декодирование", "part": "Часть 1", "title": "Задание № 2: Декодирование кодовых последовательностей (условие Фано)", "fipiSpec": {"number": "№ 2", "score": "1 балл", "time": "3 мин", "difficulty": "Базовый", "docSource": "Кодификатор и открытый банк ФИПИ ОГЭ 2026/2027"}, "theory": "<h4>Расшифровка сообщений</h4>\n     <p>Дана таблица кодов (например: А = 01, Б = 100, В = 101...) и длинная шифрограмма из цифр/символов. Нужно однозначно разбить её на буквы.</p>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Идите слева направо:</strong> Если возможны два варианта разбиения — проверьте оба до конца! Только один дойдёт до конца без тупика.</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 2</div><div class=\"task-step-desc\"><strong>Проверьте условие вопроса:</strong> Иногда просят найти только ПОВТОРЯЮЩИЕСЯ буквы или количество букв.</div></div></div>", "examples": "<div class=\"task-example-card\"><div class=\"task-example-badge\">ФИПИ</div><p><strong>Условие:</strong> Коды: А=01, Б=100, В=101, Г=11, Д=00. Расшифруйте 011001100.</p><div class=\"task-example-solution\"><strong>Решение:</strong><p>01 (А) | 100 (Б) | 11 (Г) | 00 (Д) → АБГД.</p><div class=\"task-answer-box\">Ответ: <strong>АБГД</strong></div></div></div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Нарушение порядка с конца</strong><p>Если слева много тупиков, попробуйте расшифровывать шифрограмму с конца!</p></div>"}, {"num": "3", "shortTitle": "Логика (И / ИЛИ / НЕ)", "part": "Часть 1", "title": "Задание № 3: Значение логического выражения", "fipiSpec": {"number": "№ 3", "score": "1 балл", "time": "3 мин", "difficulty": "Базовый", "docSource": "Кодификатор и открытый банк ФИПИ ОГЭ 2026/2027"}, "theory": "<h4>Законы алгебры логики</h4>\n     <div class=\"task-formula-box\">\n       <div class=\"math-row\"><strong>НЕ (инверсия):</strong> меняет условие на противоположное! ВНИМАНИЕ: НЕ (x > 5) означает <strong>x ≤ 5</strong> (знак «=» появляется!). НЕ (x чётное) → x нечётное.</div>\n       <div class=\"math-row\"><strong>И (конъюнкция, ∧):</strong> истина, когда ОБА условия верны.</div>\n       <div class=\"math-row\"><strong>ИЛИ (дизъюнкция, ∨):</strong> истина, когда ХОТЯ БЫ ОДНО верно (ложно только когда ОБА ложны!).</div>\n     </div>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Избавьтесь от «НЕ»:</strong> Сразу перепишите все части с «НЕ» без отрицания (не забудьте поменять > на ≤, < на ≥!).</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 2</div><div class=\"task-step-desc\"><strong>Найдите нужное число/слово:</strong> Подставьте граничные значения (наибольшее/наименьшее целое число) и проверьте истинность.</div></div></div>", "examples": "<div class=\"task-example-card\"><div class=\"task-example-badge\">ФИПИ</div><p><strong>Условие:</strong> Найдите наименьшее целое x, для которого истинно: (x > 16) И НЕ (x нечётное).</p><div class=\"task-example-solution\"><strong>Решение:</strong><p>НЕ (x нечётное) → x чётное. Нужно x > 16 и чётное. Наименьшее такое x = 18.</p><div class=\"task-answer-box\">Ответ: <strong>18</strong></div></div></div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Строгое / нестрогое неравенство</strong><p>При снятии «НЕ» строгое «>» всегда превращается в нестрогое «≤»!</p></div>"}, {"num": "4", "shortTitle": "Графы (кратчайший путь)", "part": "Часть 1", "title": "Задание № 4: Кратчайший путь между пунктами по таблице весов (весовой граф)", "fipiSpec": {"number": "№ 4", "score": "1 балл", "time": "4 мин", "difficulty": "Базовый", "docSource": "Кодификатор и открытый банк ФИПИ ОГЭ 2026/2027"}, "theory": "<h4>Метод дерева путей</h4>\n     <p>Дана матрица смежности (таблица расстояний между пунктами A, B, C, D, E). Нужно найти длину кратчайшего пути (иногда проходящего через обязательный пункт C, или не проходящего через него).</p>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Нарисуйте граф или дерево вариантов:</strong> Из стартового пункта выпишите все прямые дороги с их длинами и разветвляйте дальше до финиша.</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 2</div><div class=\"task-step-desc\"><strong>Отслеживайте сумму:</strong> Не возвращайтесь в уже посещённые пункты и отбрасывайте ветки, где сумма уже больше найденного минимума.</div></div></div>", "examples": "<div class=\"task-example-card\"><div class=\"task-example-badge\">ФИПИ</div><p><strong>Условие:</strong> A—B: 3, A—C: 7, B—C: 2, B—D: 6, C—D: 1. Найдите кратчайший путь из A в D.</p><div class=\"task-example-solution\"><strong>Решение:</strong><p>A→B→D = 3+6 = 9. A→B→C→D = 3+2+1 = 6. A→C→D = 7+1 = 8. Минимум = 6.</p><div class=\"task-answer-box\">Ответ: <strong>6</strong></div></div></div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Обязательный пункт</strong><p>Внимательно читайте условие: «проходящий через пункт C» (вычёркиваем пути без C) или просто кратчайший!</p></div>"}, {"num": "5", "shortTitle": "Линейный алгоритм", "part": "Часть 1", "title": "Задание № 5: Анализ алгоритма для исполнителя (Вычислитель, Альфа, Бета)", "fipiSpec": {"number": "№ 5", "score": "1 балл", "time": "3–4 мин", "difficulty": "Базовый", "docSource": "Кодификатор и открытый банк ФИПИ ОГЭ 2026/2027"}, "theory": "<h4>Исполнитель с двумя командами</h4>\n     <p>У исполнителя есть 2 команды (например: «1. прибавь 2», «2. умножь на b»). Дан маршрут команд (например, <code>11211</code>) и начальное/конечное числа. Нужно найти неизвестное b (или составить программу).</p>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Идите по цепочке команд:</strong> Подставьте переменную b в шаги алгоритма, раскрывайте скобки слева направо.</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 2</div><div class=\"task-step-desc\"><strong>Решите уравнение:</strong> Приравняйте полученное выражение к конечному числу и найдите натуральное b (b ≥ 2).</div></div></div>", "examples": "<div class=\"task-example-card\"><div class=\"task-example-badge\">ФИПИ</div><p><strong>Условие:</strong> Команды: 1) +1; 2) ×b. Программа 11211 переводит 3 в 62. Найдите b.</p><div class=\"task-example-solution\"><strong>Решение:</strong><p>3 → (+1)=4 → (+1)=5 → (×b)=5b → (+1)=5b+1 → (+1)=5b+2. Уравнение: 5b + 2 = 62 → 5b = 60 → b = 12.</p><div class=\"task-answer-box\">Ответ: <strong>12</strong></div></div></div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Порядок команд</strong><p>Выполняйте команды строго слева направо: 11211 — сначала два раза +1, потом ×b, потом ещё два раза +1.</p></div>"}, {"num": "6", "shortTitle": "Программы с «И / ИЛИ»", "part": "Часть 1", "title": "Задание № 6: Анализ программы с условным оператором (9 запусков)", "fipiSpec": {"number": "№ 6", "score": "1 балл", "time": "3–4 мин", "difficulty": "Базовый", "docSource": "Кодификатор и открытый банк ФИПИ ОГЭ 2026/2027"}, "theory": "<h4>Условие печати «YES» / «NO»</h4>\n     <p>Дана короткая программа на Python/Алгоритмическом/Паскале с условием <code>if s > 10 or t > 10:</code> (или <code>and</code>) и 9 пар входных чисел <code>(s, t)</code>. Внимание: бывает дополнительный параметр <code>A</code>!</p>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Переведите условие на русский:</strong> <code>or</code> = хотя бы одно верно; <code>and</code> = оба верны; <code>!=</code> = не равно; <code>//</code> = целая часть от деления; <code>%</code> = остаток.</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 2</div><div class=\"task-step-desc\"><strong>Проверьте все 9 пар:</strong> Поставьте + или − над каждой парой прямо в КИМе и пересчитайте плюсы (или минусы, если спрашивают «NO»!).</div></div></div>", "examples": "<div class=\"task-example-card\"><div class=\"task-example-badge\">ФИПИ</div><p><strong>Условие:</strong> Условие: s > 10 or t > 10. Пары: (1, 2), (11, 2), (1, 12), (10, 10). Сколько раз напечатает YES?</p><div class=\"task-example-solution\"><strong>Решение:</strong><p>(1,2): нет. (11,2): да. (1,12): да. (10,10): нет (знак строго > 10). Итого: 2 раза.</p><div class=\"task-answer-box\">Ответ: <strong>2</strong></div></div></div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Строгое неравенство > vs >=</strong><p>Пара (10, 10) при условии s > 10 даёт ЛОЖЬ!</p></div>"}, {"num": "7", "shortTitle": "URL-адрес файла", "part": "Часть 1", "title": "Задание № 7: Построение URL-адреса ресурса в сети Интернет", "fipiSpec": {"number": "№ 7", "score": "1 балл", "time": "2 мин", "difficulty": "Базовый", "docSource": "Кодификатор и открытый банк ФИПИ ОГЭ 2026/2027"}, "theory": "<h4>Строгий шаблон URL-адреса</h4>\n     <div class=\"task-formula-box\">\n       <div class=\"math-row\"><strong>протокол://сервер/каталог/файл</strong></div>\n       <div class=\"math-subtext\">Пример: <code>https://school6.ru/oge/math.pdf</code><br>Порядок частей ВСЕГДА одинаковый: 1) протокол (http/https/ftp) → 2) <code>://</code> → 3) домен/сервер (.ru/.org/.com) → 4) <code>/</code> → 5) путь/файл!</div>\n     </div>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Соберите адрес по шаблону:</strong> Запишите полный адрес на черновике.</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 2</div><div class=\"task-step-desc\"><strong>Замените куски на цифры/буквы:</strong> Перепишите последовательность букв без пробелов.</div></div></div>", "examples": "<div class=\"task-example-card\"><div class=\"task-example-badge\">ФИПИ</div><p><strong>Условие:</strong> Файл doc.txt на сервере site.ru по протоколу ftp.</p><div class=\"task-example-solution\"><strong>Решение:</strong><p>ftp://site.ru/doc.txt</p><div class=\"task-answer-box\">Ответ: <strong>Буквы в порядке URL</strong></div></div></div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Двоеточие и слэши</strong><p>После протокола всегда идёт <code>://</code>, а перед файлом — одиночный слэш <code>/</code>!</p></div>"}, {"num": "8", "shortTitle": "Поисковые запросы", "part": "Часть 1", "title": "Задание № 8: Поисковые запросы в Интернете (круги Эйлера)", "fipiSpec": {"number": "№ 8", "score": "1 балл", "time": "4 мин", "difficulty": "Базовый", "docSource": "Кодификатор и открытый банк ФИПИ ОГЭ 2026/2027"}, "theory": "<h4>Формула включений-исключений</h4>\n     <div class=\"task-formula-box\">\n       <div class=\"math-row\"><strong>N(A | B) = N(A) + N(B) − N(A & B)</strong></div>\n       <div class=\"math-subtext\"><strong>|</strong> (ИЛИ) — объединение (больше страниц); &nbsp; <strong>&</strong> (И) — пересечение (меньше страниц).</div>\n     </div>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Для 2 запросов:</strong> Подставьте числа прямо в формулу N(A | B) + N(A & B) = N(A) + N(B).</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 2</div><div class=\"task-step-desc\"><strong>Для 3 запросов:</strong> Нарисуйте 3 пересекающихся круга Эйлера, пронумеруйте области и сложите нужные сектора.</div></div></div>", "examples": "<div class=\"task-example-card\"><div class=\"task-example-badge\">ФИПИ</div><p><strong>Условие:</strong> Рыбак = 260, Рыбка = 400, Рыбак | Рыбка = 500. Найдите Рыбак & Рыбка.</p><div class=\"task-example-solution\"><strong>Решение:</strong><p>500 = 260 + 400 − x → x = 660 − 500 = 160.</p><div class=\"task-answer-box\">Ответ: <strong>160</strong></div></div></div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Сокращение общего слова в 3 кругах</strong><p>Если во всех запросах присутствует одно и то же слово (например «Москва & ...»), его можно мысленно вычеркнуть и решать задачу для двух оставшихся кругов!</p></div>"}, {"num": "9", "shortTitle": "Пути в графе", "part": "Часть 1", "title": "Задание № 9: Подсчёт количества путей в ориентированном графе", "fipiSpec": {"number": "№ 9", "score": "1 балл", "time": "3–4 мин", "difficulty": "Базовый", "docSource": "Кодификатор и открытый банк ФИПИ ОГЭ 2026/2027"}, "theory": "<h4>Метод динамического подсчёта на вершинах</h4>\n     <p>На схеме даны города и стрелки (дороги в одну сторону). Нужно найти число различных путей из А в К (часто: проходящих через город В, или НЕ проходящих через Е).</p>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Уберите запрещённые пути:</strong> Если нужно идти ЧЕРЕЗ город В — зачеркните все стрелки, которые обходят В стороной! Если НЕ проходить через Е — зачеркните город Е и все стрелки в/из него.</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 2</div><div class=\"task-step-desc\"><strong>Считайте веса вершин:</strong> В старте А = 1. Для каждой следующей вершины сложите числа из всех вершин, откуда в неё ведут стрелки.</div></div></div>", "examples": "<div class=\"task-example-card\"><div class=\"task-example-badge\">ФИПИ</div><p><strong>Условие:</strong> А=1; из А идут стрелки в Б и В → Б=1, В=1; из А и Б идут в Г → Г=1+1=2...</p><div class=\"task-example-solution\"><strong>Решение:</strong><p>Суммируем входящие значения до самой конечной вершины.</p><div class=\"task-answer-box\">Ответ: <strong>Сумма на финише</strong></div></div></div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Учёт только входящих стрелок</strong><p>Перед тем как посчитать вершину, убедитесь, что вы уже посчитали ВСЕ вершины, из которых в неё входят стрелки!</p></div>"}, {"num": "10", "shortTitle": "Системы счисления", "part": "Часть 1", "title": "Задание № 10: Перевод чисел между системами счисления (2, 8, 10, 16)", "fipiSpec": {"number": "№ 10", "score": "1 балл", "time": "3–4 мин", "difficulty": "Базовый", "docSource": "Кодификатор и открытый банк ФИПИ ОГЭ 2026/2027"}, "theory": "<h4>Перевод в десятичную и обратно</h4>\n     <div class=\"task-formula-box\">\n       <div class=\"math-row\"><strong>В 10-чную систему:</strong> пронумеруйте цифры справа налево с 0 (0, 1, 2, 3...) и умножьте каждую цифру на основание в этой степени.<br>Пример: 1011₂ = 1·2³ + 0·2² + 1·2¹ + 1·2⁰ = 8 + 0 + 2 + 1 = 11₁₀.</div>\n       <div class=\"math-row\"><strong>Из 10-чной в 2/8/16:</strong> делите число уголком на основание (2, 8 или 16) и выписывайте остатки снизу вверх!</div>\n       <div class=\"math-subtext\">Шестнадцатеричные цифры: A=10, B=11, C=12, D=13, E=14, F=15.</div>\n     </div>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Переведите все числа к 10-чной системе:</strong> Так проще всего сравнивать (найти максимальное/минимальное) или считать количество единиц в двоичной записи.</div></div></div>", "examples": "<div class=\"task-example-card\"><div class=\"task-example-badge\">ФИПИ</div><p><strong>Условие:</strong> Переведите 1F₁₆ и 36₈ в 10-чную систему. Укажите большее.</p><div class=\"task-example-solution\"><strong>Решение:</strong><p>1F₁₆ = 1·16 + 15 = 31. 36₈ = 3·8 + 6 = 30. Большее: 31.</p><div class=\"task-answer-box\">Ответ: <strong>31</strong></div></div></div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Запись ответа без основания</strong><p>В ответ пишется только само число (например, <code>31</code>), без индекса системы счисления!</p></div>"}, {"num": "11", "shortTitle": "Поиск в файлах (ПК)", "part": "Часть 2 (ПК)", "title": "Задание № 11: Поиск информации в файлах и каталогах", "fipiSpec": {"number": "№ 11", "score": "1 балл", "time": "4 мин", "difficulty": "Базовый", "docSource": "Кодификатор и открытый банк ФИПИ ОГЭ 2026/2027"}, "theory": "<h4>Практика на компьютере</h4>\n     <p>Нужно найти имя героя, дату, название произведения или слово в папке с текстовыми файлами (.txt, .docx, .pdf, .rtf).</p>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Используйте поиск в папке:</strong> Откройте папку с файлами и введите ключевое слово в строку поиска Проводника (или через Ctrl+F внутри файлов).</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 2</div><div class=\"task-step-desc\"><strong>Проверьте точный регистр и окончание:</strong> Выпишите ответ строго как просят в условии.</div></div></div>", "examples": "<div class=\"task-example-card\"><div class=\"task-example-badge\">ФИПИ</div><p><strong>Условие:</strong> Найдите в произведениях А.П. Чехова имя собаки из рассказа «Каштанка».</p><div class=\"task-example-solution\"><strong>Решение:</strong><p>Открываем папку Чехов → ищем файл Каштанка → находим в тексте.</p><div class=\"task-answer-box\">Ответ: <strong>Тётка</strong></div></div></div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Поиск внутри архива</strong><p>Если файлы в zip-архиве — сначала распакуйте архив, иначе поиск Windows внутри него не ищет!</p></div>"}, {"num": "12", "shortTitle": "Количество файлов (ПК)", "part": "Часть 2 (ПК)", "title": "Задание № 12: Определение количества и объёма файлов с заданным расширением", "fipiSpec": {"number": "№ 12", "score": "1 балл", "time": "3 мин", "difficulty": "Базовый", "docSource": "Кодификатор и открытый банк ФИПИ ОГЭ 2026/2027"}, "theory": "<h4>Быстрый поиск по маске</h4>\n     <div class=\"task-formula-box\">\n       <div class=\"math-row\"><strong>Синтаксис поиска Windows:</strong> <code>*.txt</code> (все txt файлы), <code>*.pdf</code>, <code>*.htm*</code> (и htm, и html).</div>\n       <div class=\"math-row\"><strong>Фильтр по размеру:</strong> можно использовать в поиске <code>размер:>1МБ</code> или сортировку по столбцу «Размер» в режиме «Таблица»!</div>\n     </div>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Зайдите в нужный подкаталог:</strong> Внимательно проверьте, в какой именно папке просят искать (например, только в «Проза», а не во всём архиве!).</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 2</div><div class=\"task-step-desc\"><strong>Введите маску расширения:</strong> Например <code>*.rtf</code> — и посмотрите на число «Элементов» в левом нижнем углу окна.</div></div></div>", "examples": "<div class=\"task-example-card\"><div class=\"task-example-badge\">ФИПИ</div><p><strong>Условие:</strong> Сколько файлов с расширением .pdf размером более 1024 КБ содержится в подкаталогах папки «Поэзия»?</p><div class=\"task-example-solution\"><strong>Решение:</strong><p>Открываем «Поэзия» → в поиске вводим <code>*.pdf</code> → сортируем по размеру → считаем подходящие.</p><div class=\"task-answer-box\">Ответ: <strong>Число файлов</strong></div></div></div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ 1 МБ vs 1024 КБ</strong><p>Windows показывает размер в КБ (округляя вверх). 1024 КБ = 1 МБ. Проверяйте точный размер в Свойствах файла, если число пограничное!</p></div>"}, {"num": "13", "shortTitle": "Презентация / Текст (ПК)", "part": "Часть 2 (ПК)", "title": "Задание № 13 (13.1 Презентация или 13.2 Форматирование текста)", "fipiSpec": {"number": "№ 13", "score": "2 балла", "time": "20–25 мин", "difficulty": "Повышенный", "docSource": "Кодификатор и открытый банк ФИПИ ОГЭ 2026/2027"}, "theory": "<h4>Что выбрать: 13.1 (презентация) или 13.2 (текст в Word/LibreOffice)?</h4>\n     <p>Обычно быстрее и точнее делать <strong>13.2 (текстовый документ)</strong> — там требования строго формализованы!</p>\n     <div class=\"task-formula-box\">\n       <div class=\"math-row\"><strong>Чек-лист для 13.2 (идеальные 2 балла):</strong></div>\n       <div class=\"math-subtext\">1. Весь шрифт одинаковый (обычно Times New Roman, 14 пт — смотрите в задании!).<br>2. Основной текст: выравнивание <strong>по ширине</strong>, красная строка (отступ первой строки <strong>1 см</strong>).<br>3. Выделите нужные слова жирным / курсивом / подчёркиванием строго как в образце.<br>4. Таблица: выравнивание текста в ячейках по центру/левому краю, одинаковая ширина столбцов, правильные границы!<br>5. Списки и интервалы: не оставляйте пустых лишних строк (Enter), настраивайте интервал через «Абзац»!</div>\n     </div>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Наберите текст без опечаток:</strong> Проверьте каждую букву и запятую (включая букву ё и тире!).</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 2</div><div class=\"task-step-desc\"><strong>Настройте параметры абзаца и шрифта:</strong> Примените отступ 1 см, межстрочный интервал и границы таблицы.</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 3</div><div class=\"task-step-desc\"><strong>Сохраните файл в нужной папке с нужным именем:</strong> Проверьте формат (.docx или .odt).</div></div></div>", "examples": "<div class=\"task-example-card\"><div class=\"task-example-badge\">ФИПИ 13.2</div><p><strong>Условие:</strong> Создать документ с текстом про озеро Байкал и таблицей характеристик (глубина, площадь).</p><div class=\"task-example-solution\"><strong>Решение:</strong><p>Набираем текст, выставляем 14 пт, отступ 1 см, создаём таблицу 2×3, выравниваем заголовки по центру и жирным.</p><div class=\"task-answer-box\">Ответ: <strong>Файл сохранён</strong></div></div></div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Опечатки в 13.2</strong><p>Допускается не более 1–2 опечаток; за лишние пробелы подряд или неправильные отступы снимают балл.</p></div>"}, {"num": "14", "shortTitle": "Таблицы Excel (ПК)", "part": "Часть 2 (ПК)", "title": "Задание № 14: Обработка большого массива данных в электронных таблицах", "fipiSpec": {"number": "№ 14", "score": "3 балла", "time": "15–20 мин", "difficulty": "Повышенный", "docSource": "Кодификатор и открытый банк ФИПИ ОГЭ 2026/2027"}, "theory": "<h4>Главные формулы Excel / LibreOffice Calc для №14</h4>\n     <div class=\"task-formula-box\">\n       <div class=\"math-row\"><strong>1. Счёт по условию:</strong> <code>=СЧЁТЕСЛИ(A2:A1001; \"Восток\")</code> или <code>=СЧЁТЕСЛИМН(...)</code></div>\n       <div class=\"math-row\"><strong>2. Среднее / Сумма по условию:</strong> <code>=СРЗНАЧЕСЛИ(диап_усл; \"усл\"; диап_знач)</code> и <code>=СУММЕСЛИ(...)</code></div>\n       <div class=\"math-row\"><strong>3. Несколько условий сразу:</strong> <code>=СЧЁТЕСЛИМН(B2:B1001; \"С\"; C2:C1001; \">50\")</code></div>\n       <div class=\"math-row\"><strong>4. Максимум / Минимум:</strong> <code>=МАКС(...)</code> / <code>=МИН(...)</code></div>\n     </div>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Ответ 1 и Ответ 2 запишите в указанные ячейки (обычно H2 и H3):</strong> Не округляйте, если просят не менее 2 знаков после запятой (форматируйте ячейку).</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 2</div><div class=\"task-step-desc\"><strong>Вопрос 3 — Круговая диаграмма:</strong> Постройте маленькую таблицу из 3 значений рядом, выделите её → Вставка → Круговая диаграмма → Добавить подписи данных → разместите рядом с ячейкой G6!</div></div></div>", "examples": "<div class=\"task-example-card\"><div class=\"task-example-badge\">ФИПИ</div><p><strong>Условие:</strong> Сколько учеников из округа «В» набрали по информатике больше 60 баллов?</p><div class=\"task-example-solution\"><strong>Решение:</strong><p><code>=СЧЁТЕСЛИМН(A2:A1001; \"В\"; D2:D1001; \">60\")</code></p><div class=\"task-answer-box\">Ответ: <strong>Формула + Диаграмма</strong></div></div></div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Диаграмма без подписей значений</strong><p>В задании №14.3 на круговой диаграмме ОБЯЗАТЕЛЬНО должны отображаться и <strong>легенда (названия)</strong>, и <strong>числовые значения</strong> на секторах!</p></div>"}, {"num": "15", "shortTitle": "Робот или Python (ПК)", "part": "Часть 2 (ПК)", "title": "Задание № 15 (15.1 Робот в КуМире или 15.2 Программа на Python)", "fipiSpec": {"number": "№ 15", "score": "2 балла", "time": "15–20 мин", "difficulty": "Повышенный", "docSource": "Кодификатор и открытый банк ФИПИ ОГЭ 2026/2027"}, "theory": "<h4>15.1 (Робот в КуМире) vs 15.2 (Код на Python)</h4>\n     <div class=\"task-formula-box\">\n       <div class=\"math-row\"><strong>Шаблон 15.1 (КуМир):</strong></div>\n       <div class=\"math-subtext\"><code>использовать Робот<br>алг<br>нач<br>  нц пока не снизу свободно<br>    закрасить; вправо<br>  кц<br>кон</code><br>Главное: алгоритм должен работать при <strong>любой</strong> длине стен и проходов (использовать циклы <code>нц пока ... кц</code>, а не просто 10 раз «вправо»!).</div>\n       <div class=\"math-row\"><strong>Шаблон 15.2 (Python — обработка последовательности):</strong></div>\n       <div class=\"math-subtext\"><code>n = int(input())<br>cnt = 0<br>for i in range(n):<br>    x = int(input())<br>    if x % 3 == 0 and x % 10 == 4:<br>        cnt += 1<br>print(cnt)</code></div>\n     </div>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>В 15.1 проверьте обстановку:</strong> Протестируйте Робота на стартовой и на изменённой (растянутой) обстановке — Робот не должен разбиться о стену!</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 2</div><div class=\"task-step-desc\"><strong>В 15.2 проверьте кратность:</strong> Кратность 3: <code>x % 3 == 0</code>; оканчивается на 4: <code>x % 10 == 4</code>; чётное: <code>x % 2 == 0</code>.</div></div></div>", "examples": "<div class=\"task-example-card\"><div class=\"task-example-badge\">ФИПИ 15.2</div><p><strong>Условие:</strong> Найти количество чисел (вводится N, затем N чисел), кратных 6 и оканчивающихся на 2.</p><div class=\"task-example-solution\"><strong>Решение:</strong><p>Условие: <code>if x % 6 == 0 and x % 10 == 2: cnt += 1</code></p><div class=\"task-answer-box\">Ответ: <strong>Программа на Python</strong></div></div></div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Ввод до 0 в 15.2</strong><p>Бывает второй тип 15.2: «вводится последовательность до числа 0». Тогда используйте цикл <code>while True: x = int(input()); if x == 0: break</code>!</p></div>"}, {"num": "16", "shortTitle": "Информационный поиск", "part": "Часть 1", "title": "Задание № 16 (В спецификации 2026 перенесено/анализ моделей и таблиц)", "fipiSpec": {"number": "№ 16", "score": "1 балл", "time": "3 мин", "difficulty": "Базовый", "docSource": "Кодификатор и открытый банк ФИПИ ОГЭ 2026/2027"}, "theory": "<h4>Итоговая проверка логики и баз данных</h4>\n     <p>В актуальной структуре ОГЭ по информатике 15 базовых/практических заданий (№1–10 в части 1, №11–15 в части 2 на компьютере — итого 19 первичных баллов!). Пункт 16 служит ориентиром на работу с файлами и проектами.</p>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Проверьте все файлы части 2:</strong> Убедитесь, что ответы к №11, 12 записаны в бланк №1, а файлы 13, 14, 15 сохранены с правильными именами!</div></div></div>", "examples": "<div class=\"task-example-card\"><div class=\"task-example-badge\">Совет ФИПИ</div><p><strong>Условие:</strong> Проверьте имена файлов перед сдачей экзамена.</p><div class=\"task-example-solution\"><strong>Решение:</strong><p>Назовите файлы строго так, как требует организатор в аудитории (например, <code>14_номер_бланка.xlsx</code>).</p><div class=\"task-answer-box\">Ответ: <strong>Готово</strong></div></div></div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Разделение бланков</strong><p>Задания №1–12 вписываются в бумажный бланк №1, а №13–15 проверяются с компьютера!</p></div>"}];
window.OGE_TASKS_BY_NUMBER.physics = [[1, "Физ. величины и приборы", "Часть 1", "Задание № 1: Сопоставление физических величин, единиц СИ и приборов", "2 балла", "3 мин", "Базовый", "<h4>Таблица главных соответствий СИ и приборов</h4>\n     <div class=\"task-formula-box\">\n       <div class=\"math-row\">• <strong>Сила</strong> (F) — Ньютон (Н) — Динамометр<br>• <strong>Давление</strong> (p) — Паскаль (Па) — Манометр / Барометр<br>• <strong>Мощность</strong> (N, P) — Ватт (Вт) — Ваттметр<br>• <strong>Работа / Энергия / Теплота</strong> (A, E, Q) — Джоуль (Дж)<br>• <strong>Сила тока</strong> (I) — Ампер (А) — Амперметр (включается последовательно!)<br>• <strong>Напряжение</strong> (U) — Вольт (В) — Вольтметр (включается параллельно!)<br>• <strong>Сопротивление</strong> (R) — Ом — Омметр / Реостат<br>• <strong>Влажность воздуха</strong> — % — Психрометр / Гигрометр</div>\n     </div>", "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Выделяйте каждую букву А, Б, В:</strong> В ответе ровно 3 цифры без пробелов.</div></div></div>", "<div class=\"task-example-card\"><div class=\"task-example-badge\">ФИПИ</div><p><strong>Условие:</strong> Сопоставьте: А) Электрический заряд Б) Сила тока В) Электрическое напряжение (1-Ампер, 2-Кулон, 3-Вольт, 4-Джоуль)</p><div class=\"task-example-solution\"><strong>Решение:</strong><p>А-2, Б-1, В-3.</p><div class=\"task-answer-box\">Ответ: <strong>213</strong></div></div></div>", "<div class=\"callout callout-warning\"><strong>⚠️ Векторная vs Скалярная величина</strong><p>Скорость, ускорение, сила, импульс — векторные (есть направление). Масса, время, температура, работа, энергия — скалярные!</p></div>"], [2, "Установление формул", "Часть 1", "Задание № 2: Сопоставление физических величин и формул", "2 балла", "3 мин", "Базовый", "<h4>Базовые формулы всех разделов</h4>\n     <div class=\"task-formula-box\">\n       <div class=\"math-row\"><strong>Механика:</strong> F = ma; &nbsp; p = mv; &nbsp; F<sub>тяж</sub> = mg; &nbsp; F<sub>арх</sub> = ρ<sub>ж</sub>gV; &nbsp; p = ρgh (гидростатическое давление); &nbsp; E<sub>к</sub> = mv²/2; &nbsp; E<sub>п</sub> = mgh.</div>\n       <div class=\"math-row\"><strong>Теплота:</strong> Q = cmΔt; &nbsp; Q = λm (плавление); &nbsp; Q = Lm (парообразование); &nbsp; Q = qm (сгорание).</div>\n       <div class=\"math-row\"><strong>Электричество:</strong> I = U/R; &nbsp; R = ρl/S; &nbsp; Q = I²Rt = UIt; &nbsp; P = UI.</div>\n     </div>", "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Проверьте размерность формулы!:</strong> Если забыли формулу, подставьте единицы измерения — они должны сойтись!</div></div></div>", "<div class=\"task-example-card\"><div class=\"task-example-badge\">ФИПИ</div><p><strong>Условие:</strong> Сопоставьте: А) Плотность вещества Б) Давление столба жидкости (1-m/V, 2-ρgh, 3-mg)</p><div class=\"task-example-solution\"><strong>Решение:</strong><p>А-1, Б-2.</p><div class=\"task-answer-box\">Ответ: <strong>12</strong></div></div></div>", "<div class=\"callout callout-warning\"><strong>⚠️ КПД механизма</strong><p>η = (A<sub>полезн</sub> / A<sub>затрач</sub>) · 100%. Полезная работа всегда МЕНЬШЕ затраченной (КПД < 100%)!</p></div>"], [3, "Физические явления", "Часть 1", "Задание № 3: Объяснение явлений природы (теплопередача, свет, звук)", "1 балл", "2–3 мин", "Базовый", "<h4>Виды теплопередачи и явления</h4>\n     <div class=\"task-formula-box\">\n       <div class=\"math-row\"><strong>1. Теплопроводность:</strong> перенос энергии без переноса вещества (металлы проводят лучше, воздух/вата/снег — плохо!).</div>\n       <div class=\"math-row\"><strong>2. Конвекция:</strong> перенос струями жидкости или газа (тёплый воздух/вода поднимаются ВВЕРХ, холодные — ВНИЗ!). В твёрдых телах и вакууме не бывает!</div>\n       <div class=\"math-row\"><strong>3. Излучение:</strong> передача тепла через вакуум (солнечный свет). Чёрные тела нагреваются быстрее белых!</div>\n     </div>", "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Определите среду:</strong> Металл → теплопроводность; нагрев воды снизу → конвекция; Солнце/костёр сбоку → излучение.</div></div></div>", "<div class=\"task-example-card\"><div class=\"task-example-badge\">ФИПИ</div><p><strong>Условие:</strong> Почему батареи отопления устанавливают внизу под окном, а форточки делают вверху?</p><div class=\"task-example-solution\"><strong>Решение:</strong><p>Благодаря явлению <strong>конвекции</strong> тёплый воздух поднимается вверх, а холодный опускается вниз.</p><div class=\"task-answer-box\">Ответ: <strong>Конвекция</strong></div></div></div>", "<div class=\"callout callout-warning\"><strong>⚠️ Испарение</strong><p>Испарение происходит при ЛЮБОЙ температуре и всегда сопровождается <strong>охлаждением</strong> жидкости (поэтому из воды выходить прохладно)!</p></div>"], {"num": "4", "shortTitle": "Текст с пропусками", "part": "Часть 1", "title": "Задание № 4: Анализ физического текста с 4 пропусками", "fipiSpec": {"number": "№ 4", "score": "2 балла", "time": "4 мин", "difficulty": "Базовый", "docSource": "Кодификатор и открытый банк ФИПИ ОГЭ 2026/2027"}, "theory": "<p>Дан текст с 4 пропусками (А, Б, В, Г) и список 7 физических терминов. Темы: электризация, тепловые процессы, звуковые волны, оптика.</p><div class='task-formula-box'><div class='math-row'>Одноимённые заряды отталкиваются, разноимённые притягиваются. Звук в вакууме НЕ распространяется!</div></div>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Читайте внимательно падежи и смысл:</strong> Вычеркните уже использованные цифры.</div></div></div>", "examples": "<div class=\"task-example-card\"><div class=\"task-example-badge\">ФИПИ</div><p><strong>Условие:</strong> Взаимодействие наэлектризованных палочек.</p><div class=\"task-example-solution\"><strong>Решение:</strong><p>Эбонит о шерсть заряжается отрицательно, стекло о шёлк — положительно.</p><div class=\"task-answer-box\">Ответ: <strong>4 цифры</strong></div></div></div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Лишние термины</strong><p>Из 7 слов используются только 4 — одно слово нельзя писать дважды!</p></div>"}, {"num": "5", "shortTitle": "Механика (расчёт)", "part": "Часть 1", "title": "Задание № 5: Расчёт по формулам кинематики и динамики", "fipiSpec": {"number": "№ 5", "score": "1 балл", "time": "3 мин", "difficulty": "Базовый", "docSource": "Кодификатор и открытый банк ФИПИ ОГЭ 2026/2027"}, "theory": "<div class='task-formula-box'><div class='math-row'>v = S/t; &nbsp; a = (v − v₀)/t; &nbsp; F = ma; &nbsp; p = mv; &nbsp; T = 1/ν (период и частота); &nbsp; λ = v·T (длина волны).</div></div>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Переведите единицы в СИ:</strong> 1 км/ч = 1/3,6 м/с; 1 г = 0,001 кг; 1 мин = 60 с.</div></div></div>", "examples": "<div class=\"task-example-card\"><div class=\"task-example-badge\">ФИПИ</div><p><strong>Условие:</strong> Тело массой 2 кг движется с ускорением 3 м/с². Найдите силу.</p><div class=\"task-example-solution\"><strong>Решение:</strong><p>F = 2 · 3 = 6 Н.</p><div class=\"task-answer-box\">Ответ: <strong>6</strong></div></div></div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Средняя скорость</strong><p>v<sub>ср</sub> = (S₁ + S₂) / (t₁ + t₂), а НЕ среднее арифметическое скоростей!</p></div>"}, {"num": "6", "shortTitle": "Статика и жидкости", "part": "Часть 1", "title": "Задание № 6: Рычаги, давление, сила Архимеда", "fipiSpec": {"number": "№ 6", "score": "1 балл", "time": "3 мин", "difficulty": "Базовый", "docSource": "Кодификатор и открытый банк ФИПИ ОГЭ 2026/2027"}, "theory": "<div class='task-formula-box'><div class='math-row'>F₁·l₁ = F₂·l₂; &nbsp; p = F/S = ρgh; &nbsp; F<sub>А</sub> = ρ<sub>ж</sub>gV<sub>погр</sub>.</div></div>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Проверьте, полностью ли тело в воде:</strong> Если тело плавает, F<sub>А</sub> = mg.</div></div></div>", "examples": "<div class=\"task-example-card\"><div class=\"task-example-badge\">ФИПИ</div><p><strong>Условие:</strong> Какое давление оказывает вода на глубине 3 м? (ρ = 1000, g = 10)</p><div class=\"task-example-solution\"><strong>Решение:</strong><p>p = 1000 · 10 · 3 = 30 000 Па = 30 кПа.</p><div class=\"task-answer-box\">Ответ: <strong>30</strong></div></div></div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Единицы площади</strong><p>1 см² = 0,0001 м² (10⁻⁴ м²)! Делите см² на 10 000!</p></div>"}, {"num": "7", "shortTitle": "Тепловые явления", "part": "Часть 1", "title": "Задание № 7: Нагревание, плавление, парообразование, КПД", "fipiSpec": {"number": "№ 7", "score": "1 балл", "time": "3 мин", "difficulty": "Базовый", "docSource": "Кодификатор и открытый банк ФИПИ ОГЭ 2026/2027"}, "theory": "<div class='task-formula-box'><div class='math-row'>Q = cmΔt; &nbsp; Q = λm; &nbsp; Q = Lm; &nbsp; Q = qm.</div></div>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Определите агрегатное состояние:</strong> Лёд (c=2100) и вода (c=4200) имеют разную теплоёмкость!</div></div></div>", "examples": "<div class=\"task-example-card\"><div class=\"task-example-badge\">ФИПИ</div><p><strong>Условие:</strong> Сколько теплоты выделится при сгорании 2 кг бензина (q = 46 МДж/кг)?</p><div class=\"task-example-solution\"><strong>Решение:</strong><p>Q = 46 · 2 = 92 МДж.</p><div class=\"task-answer-box\">Ответ: <strong>92</strong></div></div></div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Температура при плавлении</strong><p>Пока весь лёд не растает, его температура остаётся 0 °С (на графике прямая горизонтальная линия).</p></div>"}, {"num": "8", "shortTitle": "Электричество", "part": "Часть 1", "title": "Задание № 8: Цепи постоянного тока, закон Ома, мощность", "fipiSpec": {"number": "№ 8", "score": "1 балл", "time": "3 мин", "difficulty": "Базовый", "docSource": "Кодификатор и открытый банк ФИПИ ОГЭ 2026/2027"}, "theory": "<div class='task-formula-box'><div class='math-row'>I = U/R; &nbsp; R = ρl/S; &nbsp; P = U·I = I²R = U²/R; &nbsp; Q = I²Rt.</div></div>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Найдите общее сопротивление:</strong> При последовательном складываем, при параллельном 1/R = 1/R₁ + 1/R₂.</div></div></div>", "examples": "<div class=\"task-example-card\"><div class=\"task-example-badge\">ФИПИ</div><p><strong>Условие:</strong> Сила тока в лампе 0,5 А, напряжение 220 В. Найдите мощность.</p><div class=\"task-example-solution\"><strong>Решение:</strong><p>P = 220 · 0,5 = 110 Вт.</p><div class=\"task-answer-box\">Ответ: <strong>110</strong></div></div></div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Сопротивление провода</strong><p>Если провод сложить вдвое (длина в 2 раза меньше, площадь в 2 раза больше), его сопротивление упадёт в 4 раза!</p></div>"}, {"num": "9", "shortTitle": "Оптика и магнетизм", "part": "Часть 1", "title": "Задание № 9: Зеркала, линзы, магнитные полюса", "fipiSpec": {"number": "№ 9", "score": "1 балл", "time": "3 мин", "difficulty": "Базовый", "docSource": "Кодификатор и открытый банк ФИПИ ОГЭ 2026/2027"}, "theory": "<div class='task-formula-box'><div class='math-row'>D = 1 / F (F обязательно в метрах!). Угол падения = углу отражения.</div></div>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Используйте правило буравчика (правой руки):</strong> Большой палец по току → четыре пальца показывают направление линий магнитного поля.</div></div></div>", "examples": "<div class=\"task-example-card\"><div class=\"task-example-badge\">ФИПИ</div><p><strong>Условие:</strong> Фокусное расстояние линзы 20 см. Найдите оптическую силу в диоптриях.</p><div class=\"task-example-solution\"><strong>Решение:</strong><p>20 см = 0,2 м. D = 1 / 0,2 = 5 дптр.</p><div class=\"task-answer-box\">Ответ: <strong>5</strong></div></div></div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Собирающая и рассеивающая линза</strong><p>Собирающая — D > 0, рассеивающая — D < 0 (изображение всегда мнимое, прямое, уменьшенное).</p></div>"}, {"num": "10", "shortTitle": "Ядерная физика", "part": "Часть 1", "title": "Задание № 10: Строение атома, альфа- и бета-распады", "fipiSpec": {"number": "№ 10", "score": "1 балл", "time": "2 мин", "difficulty": "Базовый", "docSource": "Кодификатор и открытый банк ФИПИ ОГЭ 2026/2027"}, "theory": "<div class='task-formula-box'><div class='math-row'><sub>Z</sub><sup>A</sup>X: протонов = Z, электронов = Z, нейтронов = A − Z.</div></div>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Уравняйте верх и низ ядерной реакции:</strong> Массовое число A и зарядовое Z сохраняются.</div></div></div>", "examples": "<div class=\"task-example-card\"><div class=\"task-example-badge\">ФИПИ</div><p><strong>Условие:</strong> Ядро радия <sub>88</sub><sup>226</sup>Ra испытало α-распад. Каков заряд Z нового ядра?</p><div class=\"task-example-solution\"><strong>Решение:</strong><p>88 − 2 = 86.</p><div class=\"task-answer-box\">Ответ: <strong>86</strong></div></div></div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Нейтральный атом vs Ион</strong><p>Число протонов в ядре равно числу электронов только в нейтральном атоме.</p></div>"}, {"num": "11", "shortTitle": "Изменение величин", "part": "Часть 1", "title": "Задание № 11: Характер изменения двух величин (1-увеличится, 2-уменьшится, 3-не изменится)", "fipiSpec": {"number": "№ 11", "score": "2 балла", "time": "4 мин", "difficulty": "Повышенный", "docSource": "Кодификатор и открытый банк ФИПИ ОГЭ 2026/2027"}, "theory": "<div class='task-formula-box'><div class='math-row'>Для ползунка реостата: чем больше длина пути тока по обмотке реостата, тем больше сопротивление R!</div></div>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Запишите формулу для первой величины, потом для второй:</strong> Смотрите на каждую букву, что растёт, что падает, а что константа.</div></div></div>", "examples": "<div class=\"task-example-card\"><div class=\"task-example-badge\">ФИПИ</div><p><strong>Условие:</strong> Мяч бросили вертикально вверх. Как изменяются его кинетическая и потенциальная энергии?</p><div class=\"task-example-solution\"><strong>Решение:</strong><p>Высота растёт → E<sub>п</sub> растёт (1), скорость падает → E<sub>к</sub> падает (2).</p><div class=\"task-answer-box\">Ответ: <strong>21</strong></div></div></div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Повтор цифр</strong><p>Цифры в ответе №11 могут повторяться (например 11, 22 или 13)!</p></div>"}, {"num": "12", "shortTitle": "Изменение величин 2", "part": "Часть 1", "title": "Задание № 12: Анализ изменения величин в тепловых/электрических процессах", "fipiSpec": {"number": "№ 12", "score": "2 балла", "time": "4 мин", "difficulty": "Повышенный", "docSource": "Кодификатор и открытый банк ФИПИ ОГЭ 2026/2027"}, "theory": "<div class='task-formula-box'><div class='math-row'>• При замыкании параллельного резистора общее сопротивление цепи ВСЕГДА УМЕНЬШАЕТСЯ, а общий ток растёт!<br>• При нагревании плотность жидкости уменьшается (объём растёт, масса не меняется).</div></div>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Проверьте, что постоянно:</strong> В параллельной цепи U постоянно; в последовательной I постоянно.</div></div></div>", "examples": "<div class=\"task-example-card\"><div class=\"task-example-badge\">ФИПИ</div><p><strong>Условие:</strong> К лампе параллельно подключили ещё одну лампу. Как изменятся общее сопротивление и сила тока от батарейки?</p><div class=\"task-example-solution\"><strong>Решение:</strong><p>R уменьшится (2), I увеличится (1).</p><div class=\"task-answer-box\">Ответ: <strong>21</strong></div></div></div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Частота волны при переходе</strong><p>При переходе света или звука из одной среды в другую <strong>частота НИКОГДА не меняется</strong> (3)!</p></div>"}, {"num": "13", "shortTitle": "Анализ графиков", "part": "Часть 1", "title": "Задание № 13: Выбор 2 верных утверждений по графикам/таблицам", "fipiSpec": {"number": "№ 13", "score": "2 балла", "time": "5 мин", "difficulty": "Повышенный", "docSource": "Кодификатор и открытый банк ФИПИ ОГЭ 2026/2027"}, "theory": "<p>Даны графики движения v(t), x(t), нагревания t(τ) или таблица. Нужно выбрать ровно <strong>два</strong> верных утверждения из 5.</p><div class='task-formula-box'><div class='math-row'>На графике v(t) площадь под графиком = пройденный ПУТЬ! На графике x(t) горизонтальный участок = тело ПОКОИТСЯ (v=0)!</div></div>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Проверьте все 5 пунктов:</strong> Отсеивайте неверные с помощью расчёта по точкам графика.</div></div></div>", "examples": "<div class=\"task-example-card\"><div class=\"task-example-badge\">ФИПИ</div><p><strong>Условие:</strong> По таблице нагревания 1 кг металла определите его удельную теплоёмкость.</p><div class=\"task-example-solution\"><strong>Решение:</strong><p>c = Q / (m·Δt). Сверяем с таблицей справочных материалов КИМ!</p><div class=\"task-answer-box\">Ответ: <strong>2 цифры</strong></div></div></div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ График x(t) vs v(t)</strong><p>Обязательно смотрите, какая буква стоит на вертикальной оси: координата X или скорость V!</p></div>"}, {"num": "14", "shortTitle": "Анализ таблицы/опыта", "part": "Часть 1", "title": "Задание № 14: Выбор 2 верных утверждений по справочной таблице или таблице опыта", "fipiSpec": {"number": "№ 14", "score": "2 балла", "time": "5 мин", "difficulty": "Повышенный", "docSource": "Кодификатор и открытый банк ФИПИ ОГЭ 2026/2027"}, "theory": "<p>Обычно приводится таблица плотностей/теплоёмкостей/планет или результаты опыта с трением/пружинами.</p><div class='task-formula-box'><div class='math-row'>Тело <strong>тонет</strong> в жидкости, если ρ<sub>тела</sub> > ρ<sub>жидкости</sub>, и <strong>всплывает</strong>, если ρ<sub>тела</sub> < ρ<sub>жидкости</sub>.</div></div>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Сравнивайте числа строго по таблице:</strong> Внимательно читайте единицы в шапке таблицы (кг/м³ или г/см³: 1 г/см³ = 1000 кг/м³!).</div></div></div>", "examples": "<div class=\"task-example-card\"><div class=\"task-example-badge\">ФИПИ</div><p><strong>Условие:</strong> Будет ли кусок меди (ρ=8900) плавать в ртути (ρ=13600)?</p><div class=\"task-example-solution\"><strong>Решение:</strong><p>8900 < 13600 → да, медь будет плавать в ртути!</p><div class=\"task-answer-box\">Ответ: <strong>Верно</strong></div></div></div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Утверждения, не следующие из таблицы</strong><p>Если утверждение в целом по физике верно, но из приведённой таблицы его вывести нельзя (например, нет данных) — в №14 его НЕ выбираем!</p></div>"}, {"num": "15", "shortTitle": "Шкала прибора", "part": "Часть 1", "title": "Задание № 15: Показание прибора с учётом погрешности измерения", "fipiSpec": {"number": "№ 15", "score": "1 балл", "time": "2 мин", "difficulty": "Базовый", "docSource": "Кодификатор и открытый банк ФИПИ ОГЭ 2026/2027"}, "theory": "<div class='task-formula-box'><div class='math-row'><strong>Цена деления:</strong> C = (Ближайшие два подписанных числа) / (число делений между ними).</div><div class='math-row'><strong>Запись ответа:</strong> если погрешность Δ = 0,2, а прибор показывает 4, то пишем <code>4,00,2</code> (с тем же числом знаков после запятой, БЕЗ знаков ± и пробелов!).</div></div>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Посчитайте цену деления:</strong> Проверьте, равна ли погрешность цене деления или её половине (читайте условие!).</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 2</div><div class=\"task-step-desc\"><strong>Уравняйте знаки после запятой:</strong> Если погрешность 0,5, а показание ровно 3 — запишите 3,0!</div></div></div>", "examples": "<div class=\"task-example-card\"><div class=\"task-example-badge\">ФИПИ</div><p><strong>Условие:</strong> Показание термометра 24 °С, цена деления 1 °С, погрешность равна половине цены деления.</p><div class=\"task-example-solution\"><strong>Решение:</strong><p>Δ = 0,5. Значит показание пишем 24,0. Ответ без пробелов и знака ±: 24,00,5.</p><div class=\"task-answer-box\">Ответ: <strong>24,00,5</strong></div></div></div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Лишний знак ±</strong><p>В бланк №1 знак «±» и пробелы НЕ пишутся! Числа склеиваются подряд.</p></div>"}, {"num": "16", "shortTitle": "Вывод из эксперимента", "part": "Часть 1", "title": "Задание № 16: Анализ проведённых опытов (выбор 2 верных выводов)", "fipiSpec": {"number": "№ 16", "score": "2 балла", "time": "4 мин", "difficulty": "Повышенный", "docSource": "Кодификатор и открытый банк ФИПИ ОГЭ 2026/2027"}, "theory": "<p>Показаны 2–3 рисунка экспериментальной установки (пружины, бруски, цепи, линзы). Нужно выбрать выводы, которые <strong>непосредственно вытекают</strong> из этих опытов.</p>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Найдите, ЧТО МЕНЯЛОСЬ между опытом 1 и опытом 2:</strong> В хорошем опыте меняется ровно ОДИН параметр (например, только площадь бруска или только масса). Именно зависимость от ЭТОГО параметра и проверялась!</div></div></div>", "examples": "<div class=\"task-example-card\"><div class=\"task-example-badge\">ФИПИ</div><p><strong>Условие:</strong> Два одинаковых бруска тянут по дереву и по наждачке. Сила разная.</p><div class=\"task-example-solution\"><strong>Решение:</strong><p>Вывод: сила трения скольжения зависит от материала (шероховатости) поверхностей.</p><div class=\"task-answer-box\">Ответ: <strong>2 цифры</strong></div></div></div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Выбор «правильных», но непроверенных фраз</strong><p>Если на картинке не менялась масса — нельзя выбрать вывод «сила зависит от массы»!</p></div>"}, {"num": "17", "shortTitle": "Лабораторная работа", "part": "Часть 2 (Эксперимент)", "title": "Задание № 17: Экспериментальное задание на реальном оборудовании", "fipiSpec": {"number": "№ 17", "score": "3 балла", "time": "25–30 мин", "difficulty": "Повышенный", "docSource": "Кодификатор и открытый банк ФИПИ ОГЭ 2026/2027"}, "theory": "<h4>Идеальное оформление №17 на 3 балла</h4>\n     <div class=\"task-formula-box\">\n       <div class=\"math-row\"><strong>Обязательные 4 пункта в бланке №2:</strong></div>\n       <div class=\"math-subtext\">1. <strong>Схема</strong> установки / электрическая схема (строго по ГОСТ!).<br>2. <strong>Расчётная формула</strong> (например, k = F / Δl или R = U / I).<br>3. <strong>Результаты прямых измерений</strong> с учётом <strong>погрешности</strong> (±Δ)! (Например: l = (0,040 ± 0,002) м, m = (100 ± 2) г).<br>4. <strong>Итоговый расчёт и вывод</strong> с единицами измерения!</div>\n     </div>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Соберите установку аккуратно:</strong> Если собираете электроцепь — ключ разомкнут, амперметр последовательно, вольтметр параллельно!</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 2</div><div class=\"task-step-desc\"><strong>Запишите все погрешности из карточки оборудования:</strong> Не забудьте в бланк записать знак «±» и погрешность!</div></div></div>", "examples": "<div class=\"task-example-card\"><div class=\"task-example-badge\">ФИПИ</div><p><strong>Условие:</strong> Определите жёсткость пружины k.</p><div class=\"task-example-solution\"><strong>Решение:</strong><p>1) Схема груза на пружине; 2) k = mg / Δx; 3) m = (0,100 ± 0,002) кг, Δx = (0,025 ± 0,002) м; 4) k = 1 / 0,025 = 40 Н/м.</p><div class=\"task-answer-box\">Ответ: <strong>3 балла</strong></div></div></div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Отсутствие погрешности = −1 балл</strong><p>Забытая погрешность измерений или отсутствие схемы установки сразу снижает балл!</p></div>"}, {"num": "18", "shortTitle": "Учёные и приборы", "part": "Часть 1", "title": "Задание № 18: Научные открытия, учёные и принципы действия приборов", "fipiSpec": {"number": "№ 18", "score": "2 балла", "time": "3 мин", "difficulty": "Базовый", "docSource": "Кодификатор и открытый банк ФИПИ ОГЭ 2026/2027"}, "theory": "<div class='task-formula-box'><div class='math-row'>• <strong>Ньютон</strong> — законы механики и тяготения.<br>• <strong>Паскаль</strong> — передача давления жидкостями.<br>• <strong>Архимед</strong> — выталкивающая сила.<br>• <strong>Галилей</strong> — инерция, свободное падение.<br>• <strong>Ом</strong> — связь тока и напряжения.<br>• <strong>Фарадей</strong> — электромагнитная индукция.<br>• <strong>Эрстед</strong> — магнитное действие тока.</div></div>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Сопоставьте 2 прибора/учёных из 5 вариантов:</strong> Две цифры без пробелов.</div></div></div>", "examples": "<div class=\"task-example-card\"><div class=\"task-example-badge\">ФИПИ</div><p><strong>Условие:</strong> Кто открыл явление электромагнитной индукции?</p><div class=\"task-example-solution\"><strong>Решение:</strong><p>Майкл Фарадей (1831 г.).</p><div class=\"task-answer-box\">Ответ: <strong>Фарадей</strong></div></div></div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Эрстед vs Фарадей</strong><p>Эрстед открыл, что ток создаёт магнитное поле; Фарадей — что переменное магнитное поле создаёт ток!</p></div>"}, {"num": "19", "shortTitle": "Физический текст 1", "part": "Часть 2", "title": "Задание № 19: Понимание текста (выбор 2 верных утверждений)", "fipiSpec": {"number": "№ 19", "score": "2 балла", "time": "5 мин", "difficulty": "Базовый", "docSource": "Кодификатор и открытый банк ФИПИ ОГЭ 2026/2027"}, "theory": "<p>Даётся научно-популярный текст (половина страницы) и задания №19, 20 к нему. В №19 выберите 2 верных утверждения строго по смыслу текста.</p>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Ищите подтверждение в абзацах текста:</strong> Отбрасывайте противоречащие и додуманные утверждения.</div></div></div>", "examples": "<div class=\"task-example-card\"><div class=\"task-example-badge\">ФИПИ</div><p><strong>Условие:</strong> Текст о принципе работы термоса.</p><div class=\"task-example-solution\"><strong>Решение:</strong><p>Серебрение стенок уменьшает теплопередачу излучением, вакуум убирает теплопроводность и конвекцию.</p><div class=\"task-answer-box\">Ответ: <strong>2 цифры</strong></div></div></div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Причина и следствие</strong><p>Проверяйте, что указанная в варианте причина действительно приведена в тексте.</p></div>"}, {"num": "20", "shortTitle": "Качественный вопрос по тексту", "part": "Часть 2", "title": "Задание № 20: Развёрнутый ответ с объяснением по тексту", "fipiSpec": {"number": "№ 20", "score": "2 балла", "time": "5 мин", "difficulty": "Повышенный", "docSource": "Кодификатор и открытый банк ФИПИ ОГЭ 2026/2027"}, "theory": "<p>Нужно письменно ответить на вопрос по тексту, опираясь на физические законы и данные текста.</p>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Дай прямой ответ («Да/Нет», «Увеличится/Уменьшится»):</strong> И обязательно напиши физическое обоснование в 2–3 предложения.</div></div></div>", "examples": "<div class=\"task-example-card\"><div class=\"task-example-badge\">ФИПИ</div><p><strong>Условие:</strong> Почему капля воды на раскалённой сковороде долго не испаряется?</p><div class=\"task-example-solution\"><strong>Решение:</strong><p>Между каплей и сковородой образуется паровая подушка (эффект Лейденфроста), а пар имеет очень низкую теплопроводность.</p><div class=\"task-answer-box\">Ответ: <strong>2 балла</strong></div></div></div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Ответ без объяснения</strong><p>Ответ только «Да» без ссылки на физический закон оценивается в 0 баллов.</p></div>"}, {"num": "21", "shortTitle": "Качественная задача", "part": "Часть 2", "title": "Задание № 21: Развёрнутая качественная задача (объяснить явление)", "fipiSpec": {"number": "№ 21", "score": "2 балла", "time": "6–8 мин", "difficulty": "Повышенный", "docSource": "Кодификатор и открытый банк ФИПИ ОГЭ 2026/2027"}, "theory": "<p>Сюжет из жизни: «Что быстрее остынет?», «Почему запотевают очки?», «Почему в мороз трещат деревья?», «Зачем зимой посыпают лёд солью?».</p>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Назовите физическое явление/закон:</strong> Например: конденсация, теплопроводность, диффузия, инерция.</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 2</div><div class=\"task-step-desc\"><strong>Выстройте логическую цепочку:</strong> Причина → физический закон → следствие → ответ на вопрос.</div></div></div>", "examples": "<div class=\"task-example-card\"><div class=\"task-example-badge\">ФИПИ</div><p><strong>Условие:</strong> Почему очки запотевают, когда человек с мороза заходит в тёплую комнату?</p><div class=\"task-example-solution\"><strong>Решение:</strong><p>Холодные стёкла охлаждают тёплый влажный воздух комнаты вблизи поверхности; водяной пар становится насыщенным и конденсируется в мелкие капельки воды на стёклах.</p><div class=\"task-answer-box\">Ответ: <strong>2 балла</strong></div></div></div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Бытовое объяснение</strong><p>Избегайте бытовых слов вроде «потеют», используйте термины: <em>конденсация, точка росы, насыщенный пар</em>.</p></div>"}, {"num": "22", "shortTitle": "Расчётная задача Ч.2", "part": "Часть 2", "title": "Задание № 22: Комбинированная расчётная задача повышенной сложности (3 балла)", "fipiSpec": {"number": "№ 22", "score": "3 балла", "time": "15–20 мин", "difficulty": "Высокий", "docSource": "Кодификатор и открытый банк ФИПИ ОГЭ 2026/2027"}, "theory": "<h4>Идеальная запись задачи на 3 балла</h4>\n     <p>Обычно соединяет 2 раздела: <strong>Механика + Теплота</strong> (КПД двигателя, нагрев при торможении/ударе) или <strong>Теплота + Электричество</strong> (нагрев воды электрочайником: Q = I²Rt · η = cmΔt)!</p>\n     <div class=\"task-formula-box\"><div class='math-row'><strong>Главная связка КПД:</strong> η = Q<sub>полезн</sub> / Q<sub>затрач</sub> → Q<sub>полезн</sub> = η · Q<sub>затрач</sub> (η в долях, например 0,8!).</div></div>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Выпишите «Дано» и переведите всё в СИ:</strong> Запишите исходные формулы без цифр!</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 2</div><div class=\"task-step-desc\"><strong>Выразите искомую величину:</strong> Подставьте числа с единицами измерения и запишите слово «Ответ: ...» с единицей измерения!</div></div></div>", "examples": "<div class=\"task-example-card\"><div class=\"task-example-badge\">ФИПИ</div><p><strong>Условие:</strong> Электрочайник мощностью 2 кВт с КПД 80% нагревает 1 кг воды от 20 °С до 100 °С. Найдите время.</p><div class=\"task-example-solution\"><strong>Решение:</strong><p>Q<sub>пол</sub> = 4200·1·80 = 336 000 Дж. Q<sub>пол</sub> = η·P·t → 336 000 = 0,8·2000·t → t = 336 000 / 1600 = 210 с.</p><div class=\"task-answer-box\">Ответ: <strong>210 с</strong></div></div></div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Отсутствие исходных формул / единиц</strong><p>Если сразу подставить цифры без буквенных формул или забыть единицы в ответе, снимут балл!</p></div>"}];
window.OGE_TASKS_BY_NUMBER.chemistry = [[1, "Атом или вещество", "Часть 1", "Задание № 1: Различение понятий «химический элемент» и «простое вещество»", "1 балл", "2 мин", "Базовый", "<h4>Как отличать элемент от вещества</h4>\n     <div class=\"task-formula-box\">\n       <div class=\"math-row\"><strong>Химический элемент:</strong> входит в состав молекулы/соединения, содержится в продуктах/почве/крови, имеет заряд ядра, изотопы, валентность.</div>\n       <div class=\"math-row\"><strong>Простое вещество:</strong> имеет физические свойства (газ, цвет, запах, плотность, температура кипения), вступает в химические реакции, используется в промышленности!</div>\n     </div>", "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Прочитайте все 5 фраз:</strong> Выберите ровно ДВЕ, в которых спрашивается именно то, что просят в вопросе (либо 2 элемента, либо 2 вещества!).</div></div></div>", "<div class=\"task-example-card\"><div class=\"task-example-badge\">ФИПИ</div><p><strong>Условие:</strong> Где кислород — простое вещество? 1) входит в состав воды 2) кислород поддерживает горение 3) гемоглобин переносит кислород 4) массовая доля кислорода в воздухе 21%</p><div class=\"task-example-solution\"><strong>Решение:</strong><p>Поддерживает горение (реакция) и содержится в воздухе (смесь газов) — это простое вещество O₂ (2, 4).</p><div class=\"task-answer-box\">Ответ: <strong>24</strong></div></div></div>", "<div class=\"callout callout-warning\"><strong>⚠️ В крови / в воздухе</strong><p>В воздухе кислород — это <strong>простое вещество</strong> (газ O₂), а в составе воды/минералов/крови (соединений) — <strong>химический элемент</strong>!</p></div>"], [2, "Строение атома", "Часть 1", "Задание № 2: Электронные оболочки атомов по таблице Менделеева", "1 балл", "2 мин", "Базовый", "<h4>Шпаргалка по таблице Менделеева</h4>\n     <div class=\"task-formula-box\">\n       <div class=\"math-row\">• <strong>Заряд ядра (Z) = число протонов = число всех электронов</strong> = порядковый номер!<br>• <strong>Число электронных слоёв</strong> = номер <strong>ПЕРИОДА</strong> (строки).<br>• <strong>Число электронов на внешнем слое</strong> (для главных подгрупп A) = номер <strong>ГРУППЫ</strong>!</div>\n     </div>", "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Посчитайте кружочки/дуги:</strong> На рисунке число дуг = номер периода; число точек на самой внешней дуге = номер группы; сумма всех точек = порядковый номер!</div></div></div>", "<div class=\"task-example-card\"><div class=\"task-example-badge\">ФИПИ</div><p><strong>Условие:</strong> Определите элемент: 3 электронных слоя, на внешнем 5 электронов.</p><div class=\"task-example-solution\"><strong>Решение:</strong><p>3 период, V группа → Фосфор (P, №15).</p><div class=\"task-answer-box\">Ответ: <strong>15</strong></div></div></div>", "<div class=\"callout callout-warning\"><strong>⚠️ Порядок записи ответа</strong><p>Внимательно смотрите: просят записать номер элемента (X) и номер периода/группы (Y) — без пробелов!</p></div>"], [3, "Периодический закон", "Часть 1", "Задание № 3: Изменение свойств элементов (радиус, электроотрицательность, металлы)", "1 балл", "2–3 мин", "Базовый", "<h4>Закономерности в таблице Менделеева</h4>\n     <div class=\"task-formula-box\">\n       <div class=\"math-row\">• <strong>К Фтору (F, правый верхний угол):</strong> растут <strong>неметаллические</strong> свойства, <strong>электроотрицательность (ЭО)</strong>, кислотные свойства.<br>• <strong>К Францию (Fr, левый нижний угол):</strong> растут <strong>радиус атома</strong>, <strong>металлические</strong> (восстановительные) свойства, основные свойства!</div>\n     </div>", "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Отметьте 3 элемента на таблице Менделеева:</strong> Посмотрите, в каком направлении от F или к F они лежат и расставьте цифры!</div></div></div>", "<div class=\"task-example-card\"><div class=\"task-example-badge\">ФИПИ</div><p><strong>Условие:</strong> Расположите в порядке увеличения неметаллических свойств: 1) C  2) N  3) B</p><div class=\"task-example-solution\"><strong>Решение:</strong><p>Они идут в 2 периоде: B → C → N (ближе к F — сильнее неметалл).</p><div class=\"task-answer-box\">Ответ: <strong>312</strong></div></div></div>", "<div class=\"callout callout-warning\"><strong>⚠️ Возрастание vs Убывание</strong><p>Всегда перечитывайте, просят в порядке ВОЗРАСТАНИЯ или УБЫВАНИЯ!</p></div>"], [4, "Валентность и степень окисления", "Часть 1", "Задание № 4: Определение степени окисления элемента в формуле", "2 балла", "3 мин", "Базовый", "<h4>Постоянные степени окисления</h4>\n     <div class=\"task-formula-box\">\n       <div class=\"math-row\">• <strong>Простые вещества:</strong> всегда 0 (O₂, Fe, N₂).<br>• <strong>Кислород (O):</strong> почти всегда −2 (кроме H₂O₂ где −1, и OF₂ где +2).<br>• <strong>Водород (H):</strong> +1 с неметаллами (HCl, H₂O), −1 с металлами (NaH).<br>• <strong>Щелочные (IА: Li, Na, K):</strong> всегда +1; <strong>IIА (Mg, Ca, Ba, Zn):</strong> всегда +2; <strong>Al:</strong> всегда +3; <strong>F:</strong> всегда −1.<br>• <strong>Главное правило:</strong> сумма всех степеней окисления в молекуле равна <strong>0</strong>!</div>\n     </div>", "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Проставьте известные (O = −2, H = +1, Na = +1):</strong> Умножьте на индексы и найдите неизвестную степень через простое уравнение (сумма = 0).</div></div></div>", "<div class=\"task-example-card\"><div class=\"task-example-badge\">ФИПИ</div><p><strong>Условие:</strong> Найдите степень окисления хрома в K₂Cr₂O₇.</p><div class=\"task-example-solution\"><strong>Решение:</strong><p>2·(+1) + 2·x + 7·(−2) = 0 → 2 + 2x − 14 = 0 → 2x = 12 → x = +6.</p><div class=\"task-answer-box\">Ответ: <strong>+6</strong></div></div></div>", "<div class=\"callout callout-warning\"><strong>⚠️ Знак + или −</strong><p>Степень окисления всегда пишется со знаком (+6, −2), а валентность — римскими цифрами без знака (VI, II)!</p></div>"], [5, "Химическая связь", "Часть 1", "Задание № 5: Виды химической связи (ионная, ковалентная, металлическая)", "1 балл", "2 мин", "Базовый", "<h4>Шпаргалка по 4 типам связи</h4>\n     <div class=\"task-formula-box\">\n       <div class=\"math-row\">1. <strong>Ионная:</strong> Металл + Неметалл (или ион аммония NH₄⁺ + Неметалл): NaCl, CaO, K₂SO₄, NH₄NO₃.<br>2. <strong>Ковалентная неполярная:</strong> Одинаковые неметаллы (O₂, N₂, Cl₂, H₂, P₄).<br>3. <strong>Ковалентная полярная:</strong> Разные неметаллы (H₂O, CO₂, NH₃, HCl, SO₂).<br>4. <strong>Металлическая:</strong> Чистые металлы и сплавы (Fe, Cu, Al).</div>\n     </div>", "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Посмотрите на состав формулы:</strong> Есть металл и неметалл → ионная; только одинаковые неметаллы → неполярная; разные неметаллы → полярная.</div></div></div>", "<div class=\"task-example-card\"><div class=\"task-example-badge\">ФИПИ</div><p><strong>Условие:</strong> Выберите два вещества с ионной связью: 1) HCl  2) KBr  3) O₂  4) Na₂O  5) CH₄</p><div class=\"task-example-solution\"><strong>Решение:</strong><p>KBr и Na₂O состоят из металла и неметалла.</p><div class=\"task-answer-box\">Ответ: <strong>24</strong></div></div></div>", "<div class=\"callout callout-warning\"><strong>⚠️ Соли аммония (NH₄Cl)</strong><p>В соединениях с группой NH₄⁺ (хотя там только неметаллы!) связь тоже <strong>ИОННАЯ</strong>!</p></div>"], [6, "Свойства элементов (2 из 5)", "Часть 1", "Задание № 6: Сравнение характеристик двух элементов (P/N, Mg/Ca, Cl/Br)", "1 балл", "3 мин", "Базовый", "<p>Даны 5 утверждений о двух элементах (например, о магнии и алюминии). Нужно выбрать 2 верных утверждения для обоих сразу.</p>", "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Найдите оба элемента в ПСХЭ:</strong> Проверьте: в одном периоде (одинаково слоёв) или в одной группе (одинаково внешних электронов).</div></div></div>", "<div class=\"task-example-card\"><div class=\"task-example-badge\">ФИПИ</div><p><strong>Условие:</strong> Верно ли для Na и K: 1) одинаковое число слоёв 2) образуют оксиды R₂O 3) металлы?</p><div class=\"task-example-solution\"><strong>Решение:</strong><p>1 — ложь (3 и 4 слоя), 2 и 3 — верно (оба в IA группе).</p><div class=\"task-answer-box\">Ответ: <strong>23</strong></div></div></div>", "<div class=\"callout callout-warning\"><strong>⚠️ Высший оксид и летучее водородное соединение</strong><p>Летучие водородные соединения (типа HCl, NH₃, CH₄) образуют ТОЛЬКО неметаллы!</p></div>"], [7, "Классификация веществ", "Часть 1", "Задание № 7: Оксиды, основания, амфотерные гидроксиды, кислоты, соли", "1 балл", "2–3 мин", "Базовый", "<h4>4 класса неорганических веществ</h4>\n     <div class=\"task-formula-box\">\n       <div class=\"math-row\">• <strong>Оксиды:</strong> элемент + O (несолеобразующие: CO, NO, N₂O, SiO!). Основные (Ме +1/+2: Na₂O, CuO), Амфотерные (ZnO, Al₂O₃, BeO, Fe₂O₃, Cr₂O₃), Кислотные (НеМе или Ме +5..+7: SO₃, CrO₃, Mn₂O₇).<br>• <strong>Основания:</strong> Ме + OH (щёлочи — растворимые по таблице растворимости!).<br>• <strong>Кислоты:</strong> H + кислотный остаток (H₂SO₄, HNO₃, HCl).<br>• <strong>Соли:</strong> Ме (или NH₄⁺) + кислотный остаток (средние, кислые NaHCO₃, основные (CuOH)₂CO₃).</div>\n     </div>", "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Сначала определите класс, потом подвид:</strong> Оксид металла в степени +3/+4 (Al₂O₃, Fe₂O₃) и ZnO, BeO — амфотерные!</div></div></div>", "<div class=\"task-example-card\"><div class=\"task-example-badge\">ФИПИ</div><p><strong>Условие:</strong> Найдите кислотный оксид и основание: 1) CO  2) SO₂  3) NaOH  4) Al(OH)₃</p><div class=\"task-example-solution\"><strong>Решение:</strong><p>SO₂ — кислотный оксид; NaOH — основание (щёлочь). Al(OH)₃ — амфотерный гидроксид, CO — несолеобразующий!</p><div class=\"task-answer-box\">Ответ: <strong>23</strong></div></div></div>", "<div class=\"callout callout-warning\"><strong>⚠️ Запоминалка несолеобразующих оксидов</strong><p><strong>CO, NO, N₂O, SiO</strong> — НИКОГДА не реагируют со щелочами и кислотами с образованием солей!</p></div>"], [8, "Свойства простых и оксидов", "Часть 1", "Задание № 8: С какими веществами реагирует данный оксид / простое вещество", "1 балл", "3–4 мин", "Повышенный", "<h4>Правило «противоположностей»</h4>\n     <div class=\"task-formula-box\">\n       <div class=\"math-row\">• <strong>Основный</strong> оксид (CuO, CaO) реагирует с <strong>кислотами</strong> и <strong>кислотными</strong> оксидами.<br>• <strong>Кислотный</strong> оксид (SO₂, CO₂) реагирует с <strong>основаниями (щелочами)</strong>, <strong>основными</strong> оксидами и водой (кроме SiO₂!).<br>• <strong>Амфотерный</strong> оксид (ZnO, Al₂O₃) реагирует И с кислотами, И со щелочами!</div>\n     </div>", "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Отсекайте пары с «таким же» классом:</strong> Кислотный оксид с кислотой НЕ реагирует; основный оксид со щёлочью НЕ реагирует!</div></div></div>", "<div class=\"task-example-card\"><div class=\"task-example-badge\">ФИПИ</div><p><strong>Условие:</strong> С какими двумя веществами реагирует CuO: 1) NaOH  2) HCl  3) H₂  4) K₂SO₄  5) O₂</p><div class=\"task-example-solution\"><strong>Решение:</strong><p>CuO (основный оксид) реагирует с кислотой (HCl) и восстанавливается водородом (H₂) до меди.</p><div class=\"task-answer-box\">Ответ: <strong>23</strong></div></div></div>", "<div class=\"callout callout-warning\"><strong>⚠️ SiO₂ (песок) и вода</strong><p>Оксид кремния SiO₂ — кислотный оксид, но он НЕ растворяется и НЕ реагирует с водой (иначе бы пляжи растворились)!</p></div>"], {"num": "9", "shortTitle": "Реакции (2 вещества)", "part": "Часть 1", "title": "Задание № 9: Сопоставление исходных веществ и продуктов реакции", "fipiSpec": {"number": "№ 9", "score": "2 балла", "time": "4 мин", "difficulty": "Повышенный", "docSource": "Кодификатор и открытый банк ФИПИ ОГЭ 2026/2027"}, "theory": "<div class='task-formula-box'><div class='math-row'>Особые случаи ФИПИ:<br>• Fe + HCl → FeCl₂ + H₂ (а Fe + Cl₂ → FeCl₃!)<br>• Металл + конц. H₂SO₄ / HNO₃ → водород H₂ НЕ выделяется! (идут соли + SO₂/NO₂/NO + H₂O).<br>• Cu стоит ПОСЛЕ H₂ в ряду активности → не вытесняет водород из обычных кислот (HCl, разб. H₂SO₄).</div></div>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Проверяйте степени окисления продуктов:</strong> У железа с соляной кислотой всегда +2, а с чистым хлором Cl₂ или азотной кислотой — +3!</div></div></div>", "examples": "<div class=\"task-example-card\"><div class=\"task-example-badge\">ФИПИ</div><p><strong>Условие:</strong> NaOH + CO₂ (избыток) = ?</p><div class=\"task-example-solution\"><strong>Решение:</strong><p>При избытке CO₂ образуется кислая соль NaHCO₃, при избытке щёлочи — средняя Na₂CO₃ + H₂O.</p><div class=\"task-answer-box\">Ответ: <strong>Продукт реакции</strong></div></div></div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Разложение нитратов и карбонатов</strong><p>При нагревании нерастворимые основания и карбонаты (кроме Na₂CO₃, K₂CO₃) разлагаются на оксид + воду / CO₂!</p></div>"}, {"num": "10", "shortTitle": "Генетическая связь", "part": "Часть 1", "title": "Задание № 10: Взаимосвязь веществ различных классов (кто с кем реагирует)", "fipiSpec": {"number": "№ 10", "score": "2 балла", "time": "4–5 мин", "difficulty": "Повышенный", "docSource": "Кодификатор и открытый банк ФИПИ ОГЭ 2026/2027"}, "theory": "<p>Даны 3 вещества (А, Б, В) и 4 пары реагентов (1–4). Нужно подобрать для каждого вещества пару, с обоими компонентами которой оно реагирует.</p>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Идите методом исключения:</strong> Проверяйте таблицу растворимости: в реакциях обмена обязательно должен выпасть осадок (↓), выделиться газ (↑) или образоваться вода (H₂O)!</div></div></div>", "examples": "<div class=\"task-example-card\"><div class=\"task-example-badge\">ФИПИ</div><p><strong>Условие:</strong> Выберите пару, реагирующую с H₂SO₄: 1) Cu, NaCl  2) BaCl₂, KOH  3) CO₂, O₂</p><div class=\"task-example-solution\"><strong>Решение:</strong><p>H₂SO₄ + BaCl₂ → BaSO₄↓ (белый осадок) и H₂SO₄ + KOH → K₂SO₄ + H₂O.</p><div class=\"task-answer-box\">Ответ: <strong>2</strong></div></div></div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Осадок с нерастворимым основанием</strong><p>Соли НЕ реагируют с нерастворимыми основаниями (например Fe(OH)₂ + NaCl не идёт)! Для реакции двух солей ОБЕ исходные соли должны быть растворимы!</p></div>"}, {"num": "11", "shortTitle": "Типы реакций", "part": "Часть 1", "title": "Задание № 11: Окислительно-восстановительные (ОВР) и типы реакций (соединение/обмен)", "fipiSpec": {"number": "№ 11", "score": "1 балл", "time": "2 мин", "difficulty": "Базовый", "docSource": "Кодификатор и открытый банк ФИПИ ОГЭ 2026/2027"}, "theory": "<div class='task-formula-box'><div class='math-row'>• <strong>Соединение:</strong> A + B → C<br>• <strong>Разложение:</strong> C → A + B<br>• <strong>Замещение:</strong> простое + сложное → простое + сложное (всегда ОВР!)<br>• <strong>Обмен:</strong> сложное + сложное → сложное + сложное (НИКОГДА не ОВР — степени окисления не меняются!).</div></div>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Посмотрите, есть ли в реакции простые вещества:</strong> Если есть простое вещество (O₂, H₂, Fe, Cl₂) — реакция почти всегда ОВР!</div></div></div>", "examples": "<div class=\"task-example-card\"><div class=\"task-example-badge\">ФИПИ</div><p><strong>Условие:</strong> Выберите 2 реакции замещения: 1) Zn + 2HCl → ZnCl₂ + H₂  2) CaCO₃ → CaO + CO₂  3) Fe + CuSO₄ → FeSO₄ + Cu</p><div class=\"task-example-solution\"><strong>Решение:</strong><p>1 и 3 — простое + сложное.</p><div class=\"task-answer-box\">Ответ: <strong>13</strong></div></div></div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Реакция обмена vs ОВР</strong><p>В реакции нейтрализации (кислота + щёлочь) степени окисления НЕ меняются — это НЕ ОВР.</p></div>"}, {"num": "12", "shortTitle": "Качественные реакции", "part": "Часть 1", "title": "Задание № 12: Признаки реакций (цвета осадков, газы, запах)", "fipiSpec": {"number": "№ 12", "score": "2 балла", "time": "3 мин", "difficulty": "Базовый", "docSource": "Кодификатор и открытый банк ФИПИ ОГЭ 2026/2027"}, "theory": "<h4>Цвета осадков и газов, которые надо знать наизусть!</h4>\n     <div class=\"task-formula-box\">\n       <div class=\"math-row\">• <strong>Белые осадки:</strong> BaSO₄ (не раств. даже в кислотах!), AgCl (творожистый), CaCO₃, Al(OH)₃.<br>• <strong>Цветные осадки:</strong> Cu(OH)₂ — голубой; Fe(OH)₃ — бурый (ржавый); Fe(OH)₂ — серо-зелёный; AgBr — бледно-жёлтый; AgI — жёлтый; CuS, PbS — чёрные.<br>• <strong>Газы:</strong> CO₂ (без запаха, мутит известковую воду), NH₃ (резкий запах), H₂S (запах тухлых яиц), SO₂ (запах жжёной спички).</div>\n     </div>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Соедините ионы из левой и правой части:</strong> Найдите по таблице растворимости, какая пара ионов даёт «Н» (осадок) или газ (H₂CO₃ → CO₂↑ + H₂O).</div></div></div>", "examples": "<div class=\"task-example-card\"><div class=\"task-example-badge\">ФИПИ</div><p><strong>Условие:</strong> Признак реакции BaCl₂ + Na₂SO₄?</p><div class=\"task-example-solution\"><strong>Решение:</strong><p>Образуется белый осадок BaSO₄.</p><div class=\"task-answer-box\">Ответ: <strong>Выпадение белого осадка</strong></div></div></div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Забытый газ NH₃</strong><p>При нагревании солей аммония со щелочами (NH₄Cl + NaOH) выделяется газ аммиак NH₃ с резким запахом!</p></div>"}, {"num": "13", "shortTitle": "Электролиты / Диссоциация", "part": "Часть 1", "title": "Задание № 13: Электролитическая диссоциация (сильные электролиты и ионы)", "fipiSpec": {"number": "№ 13", "score": "1 балл", "time": "2 мин", "difficulty": "Базовый", "docSource": "Кодификатор и открытый банк ФИПИ ОГЭ 2026/2027"}, "theory": "<div class='task-formula-box'><div class='math-row'>На ионы диссоциируют ТОЛЬКО растворимые соли, сильные кислоты и щёлочи! (Осадки, газы, вода H₂O и оксиды на ионы НЕ распадаются!).<br>Пример: Ca(NO₃)₂ → Ca²⁺ + 2NO₃⁻ (итого 1 + 2 = <strong>3 моль</strong> ионов!).</div></div>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Проверьте растворимость вещества:</strong> Посчитайте коэффициенты перед ионами после диссоциации.</div></div></div>", "examples": "<div class=\"task-example-card\"><div class=\"task-example-badge\">ФИПИ</div><p><strong>Условие:</strong> Сколько моль анионов образуется при диссоциации 1 моль Al₂(SO₄)₃?</p><div class=\"task-example-solution\"><strong>Решение:</strong><p>Al₂(SO₄)₃ → 2Al³⁺ + 3SO₄²⁻. Анионов (отрицательных ионов) 3 моль.</p><div class=\"task-answer-box\">Ответ: <strong>3</strong></div></div></div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Катионы (+) vs Анионы (−)</strong><p>Внимательно читайте: спрашивают общее число ионов, число катионов (+) или число анионов (−)!</p></div>"}, {"num": "14", "shortTitle": "Ионные уравнения", "part": "Часть 1", "title": "Задание № 14: Выбор пары веществ для данного сокращённого ионного уравнения", "fipiSpec": {"number": "№ 14", "score": "1 балл", "time": "3 мин", "difficulty": "Базовый", "docSource": "Кодификатор и открытый банк ФИПИ ОГЭ 2026/2027"}, "theory": "<p>Дано сокращённое ионное уравнение, например: <code>Cu²⁺ + 2OH⁻ = Cu(OH)₂↓</code>. Нужно выбрать 2 исходных вещества из 6.</p>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Оба вещества должны быть РАСТВОРИМЫМИ (сильными электролитами)!:</strong> Нельзя брать нерастворимый CuO или слабую кислоту! Берём растворимую соль (CuSO₄) и щёлочь (NaOH/KOH).</div></div></div>", "examples": "<div class=\"task-example-card\"><div class=\"task-example-badge\">ФИПИ</div><p><strong>Условие:</strong> Для уравнения H⁺ + OH⁻ = H₂O подойдут:</p><div class=\"task-example-solution\"><strong>Решение:</strong><p>Любая сильная кислота (HCl, HNO₃, H₂SO₄) + любая щёлочь (NaOH, KOH, Ba(OH)₂).</p><div class=\"task-answer-box\">Ответ: <strong>2 цифры</strong></div></div></div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Осторожно с Ba(OH)₂ + H₂SO₄</strong><p>Пара Ba(OH)₂ + H₂SO₄ кроме воды H₂O даёт ещё и осадок BaSO₄, поэтому её сокращённое уравнение НЕ просто H⁺ + OH⁻ = H₂O!</p></div>"}, {"num": "15", "shortTitle": "Процессы окисления", "part": "Часть 1", "title": "Задание № 15: Определение окислителя / восстановителя по схеме перехода электронов", "fipiSpec": {"number": "№ 15", "score": "1 балл", "time": "2 мин", "difficulty": "Базовый", "docSource": "Кодификатор и открытый банк ФИПИ ОГЭ 2026/2027"}, "theory": "<div class='task-formula-box'><div class='math-row'>• <strong>Окислитель</strong> — грабитель (забирает электроны «+ē», степень окисления ПОНИЖАЕТСЯ, сам восстанавливается).<br>• <strong>Восстановитель</strong> — добряк (отдаёт электроны «−ē», степень окисления ПОВЫШАЕТСЯ, сам окисляется).</div></div>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Сравните заряд слева и справа от стрелки:</strong> Увеличился (например 0 → +2) — отдал 2 электрона → ВОССТАНОВИТЕЛЬ. Уменьшился (+5 → +2) — принял 3 электрона → ОКИСЛИТЕЛЬ.</div></div></div>", "examples": "<div class=\"task-example-card\"><div class=\"task-example-badge\">ФИПИ</div><p><strong>Условие:</strong> S⁻² − 2ē → S⁰ — это процесс...?</p><div class=\"task-example-solution\"><strong>Решение:</strong><p>Отдаёт электроны (степень растёт с −2 до 0) → процесс окисления (сам восстановитель).</p><div class=\"task-answer-box\">Ответ: <strong>Окисление</strong></div></div></div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Процесс vs Роль элемента</strong><p>Элемент-восстановитель участвует в процессе ОКИСЛЕНИЯ, а окислитель — в процессе ВОССТАНОВЛЕНИЯ!</p></div>"}, {"num": "16", "shortTitle": "Правила работы в лаборатории", "part": "Часть 1", "title": "Задание № 16: Техника безопасности, разделение смесей и ТБ", "fipiSpec": {"number": "№ 16", "score": "1 балл", "time": "2 мин", "difficulty": "Базовый", "docSource": "Кодификатор и открытый банк ФИПИ ОГЭ 2026/2027"}, "theory": "<div class='task-formula-box'><div class='math-row'>• <strong>Фильтрование:</strong> твёрдое нерастворимое + жидкость (песок и вода).<br>• <strong>Выпаривание / кристаллизация:</strong> растворимое твёрдое + вода (соль и вода).<br>• <strong>Делительная воронка:</strong> две несмешивающиеся жидкости (масло и вода).<br>• <strong>Перегонка (дистилляция):</strong> две смешивающиеся жидкости с разной t° кипения (спирт и вода).<br>• <strong>Разбавление H₂SO₄:</strong> льют <strong>КИСЛОТУ В ВОДУ</strong> тонкой струйкой!</div></div>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Проверьте, что ТБ не нарушена:</strong> Нагревание пробирки в руках, питьё/пробование на вкус и нюхание прямо из горлышка ЗАПРЕЩЕНЫ!</div></div></div>", "examples": "<div class=\"task-example-card\"><div class=\"task-example-badge\">ФИПИ</div><p><strong>Условие:</strong> Как разделить смесь воды и подсолнечного масла?</p><div class=\"task-example-solution\"><strong>Решение:</strong><p>С помощью делительной воронки (они не смешиваются и имеют разную плотность).</p><div class=\"task-answer-box\">Ответ: <strong>Делительная воронка</strong></div></div></div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Индикаторы</strong><p>Лакмус в кислоте красный, в щёлочи синий. Фенолфталеин в щёлочи малиновый (в кислоте и воде бесцветный!). Метилоранж в кислоте красный, в щёлочи жёлтый.</p></div>"}, {"num": "17", "shortTitle": "Распознавание веществ", "part": "Часть 1", "title": "Задание № 17: Выбор реактива для различия двух веществ в пробирках", "fipiSpec": {"number": "№ 17", "score": "2 балла", "time": "4 мин", "difficulty": "Повышенный", "docSource": "Кодификатор и открытый банк ФИПИ ОГЭ 2026/2027"}, "theory": "<p>Даны 3 пары растворов (А, Б, В) и 4 реактива. Нужно подобрать реактив, с которым одна пробирка даст видимый признак (осадок/газ/цвет), а вторая — нет (или другой цвет).</p>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Проверьте обе пробирки в паре:</strong> Нельзя брать реактив, который даёт БЕЛЫЙ осадок в ОБЕИХ пробирках — вы их не отличите!</div></div></div>", "examples": "<div class=\"task-example-card\"><div class=\"task-example-badge\">ФИПИ</div><p><strong>Условие:</strong> Чем отличить NaCl от Na₂CO₃?</p><div class=\"task-example-solution\"><strong>Решение:</strong><p>Любой сильной кислотой (HCl): с Na₂CO₃ пойдёт газ CO₂↑ (пузырьки), а с NaCl ничего не произойдёт.</p><div class=\"task-answer-box\">Ответ: <strong>HCl</strong></div></div></div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Свет/Осадок</strong><p>Если в обеих пробирках с AgNO₃ выпадает осадок, проверяйте цвет: AgCl белый, AgBr бледно-жёлтый, AgI жёлтый — их отличить можно!</p></div>"}, {"num": "18", "shortTitle": "Массовая доля в формуле", "part": "Часть 1", "title": "Задание № 18: Расчёт массовой доли элемента в химическом соединении (%)", "fipiSpec": {"number": "№ 18", "score": "1 балл", "time": "2 мин", "difficulty": "Базовый", "docSource": "Кодификатор и открытый банк ФИПИ ОГЭ 2026/2027"}, "theory": "<div class='task-formula-box'><div class='math-row'><strong>w(Э) = (n · A<sub>r</sub>(Э) / M<sub>r</sub>(вещества)) · 100%</strong></div><div class='math-subtext'>Атомные массы A<sub>r</sub> берём из таблицы Менделеева (округляем до целых, НО <strong>Cl = 35,5</strong>!).</div></div>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Посчитайте общую молярную массу M<sub>r</sub>:</strong> Разделите массу нужного элемента на M<sub>r</sub> и умножьте на 100%.</div></div></div>", "examples": "<div class=\"task-example-card\"><div class=\"task-example-badge\">ФИПИ</div><p><strong>Условие:</strong> Вычислите массовую долю азота в аммиачной селитре NH₄NO₃ (в %).</p><div class=\"task-example-solution\"><strong>Решение:</strong><p>M<sub>r</sub> = 14 + 4 + 14 + 48 = 80. Азота 2 атома: 2·14 = 28. w = (28 / 80) · 100% = 35%.</p><div class=\"task-answer-box\">Ответ: <strong>35</strong></div></div></div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Округление в №18</strong><p>Обратите внимание: если в №18 просят округлить до десятых или до целых — округляйте по правилам математики в самом конце!</p></div>"}, {"num": "19", "shortTitle": "Применение формулы (№18+19)", "part": "Часть 1", "title": "Задание № 19: Расчёт массы элемента в данной массе удобрения/лекарства", "fipiSpec": {"number": "№ 19", "score": "1 балл", "time": "2 мин", "difficulty": "Базовый", "docSource": "Кодификатор и открытый банк ФИПИ ОГЭ 2026/2027"}, "theory": "<p>Прямое продолжение №18! Зная массовую долю w из №18, найдите массу чистого элемента в данной массе вещества (например, сколько грамм азота в 400 г селитры).</p>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Умножьте массу из №19 на долю из №18:</strong> m(элемента) = m(вещества) · (w / 100).</div></div></div>", "examples": "<div class=\"task-example-card\"><div class=\"task-example-badge\">ФИПИ</div><p><strong>Условие:</strong> Сколько граммов азота получит почва при внесении 200 г NH₄NO₃ (из №18 w = 35%)?</p><div class=\"task-example-solution\"><strong>Решение:</strong><p>200 · 0,35 = 70 г.</p><div class=\"task-answer-box\">Ответ: <strong>70</strong></div></div></div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Килограммы и граммы</strong><p>Внимательно смотрите единицы измерения: в условии кг или граммы, и в чём просят ответ!</p></div>"}, {"num": "20", "shortTitle": "Электронный баланс (ОВР)", "part": "Часть 2", "title": "Задание № 20: Составление ОВР методом электронного баланса", "fipiSpec": {"number": "№ 20", "score": "3 балла", "time": "8–10 мин", "difficulty": "Повышенный", "docSource": "Кодификатор и открытый банк ФИПИ ОГЭ 2026/2027"}, "theory": "<h4>Идеальная запись на 3 балла</h4>\n     <div class=\"task-formula-box\">\n       <div class=\"math-row\">1. Проставьте степени окисления у меняющихся элементов.<br>2. Запишите 2 полуреакции электронного баланса (с учётом индексов типа O₂⁰ или Cl₂⁰!).<br>3. Найдите наименьшее общее кратное и коэффициенты.<br>4. Расставьте коэффициенты в уравнении (уравнивайте сначала металлы, потом неметаллы, потом H, и в конце проверьте по O!).<br>5. ОБЯЗАТЕЛЬНО напишите: <strong>Кто окислитель, а кто восстановитель!</strong></div>\n     </div>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Пишите чётко вещество целиком в ответе:</strong> Например: «KMnO₄ (за счёт Mn⁺⁷) — окислитель».</div></div></div>", "examples": "<div class=\"task-example-card\"><div class=\"task-example-badge\">ФИПИ</div><p><strong>Условие:</strong> Cu + 4HNO₃(конц) → Cu(NO₃)₂ + 2NO₂ + 2H₂O</p><div class=\"task-example-solution\"><strong>Решение:</strong><p>Cu⁰ − 2ē → Cu⁺² (восст.) | 1<br>N⁺⁵ + 1ē → N⁺⁴ (окисл.) | 2</p><div class=\"task-answer-box\">Ответ: <strong>3 балла</strong></div></div></div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Забытый окислитель/восстановитель = −1 балл</strong><p>Без явного указания окислителя и восстановителя максимум 2 балла вместо 3!</p></div>"}, {"num": "21", "shortTitle": "Цепочка превращений", "part": "Часть 2", "title": "Задание № 21: Осуществление цепочки превращений + сокращённое ионное уравнение", "fipiSpec": {"number": "№ 21", "score": "4 балла", "time": "10–12 мин", "difficulty": "Повышенный", "docSource": "Кодификатор и открытый банк ФИПИ ОГЭ 2026/2027"}, "theory": "<p>Нужно написать 3 уравнения реакций по цепочке A → B → C → D и для указанной реакции (обычно обмена) записать <strong>сокращённое ионное уравнение</strong>.</p>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Сначала расставьте коэффициенты в 3 реакциях:</strong> Не забывайте условия/стрелки при желании (но главное — правильные формулы и коэффициенты!).</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 2</div><div class=\"task-step-desc\"><strong>В 4-м действии распишите ионы:</strong> Не раскладывайте на ионы осадки, газы, воду и оксиды!</div></div></div>", "examples": "<div class=\"task-example-card\"><div class=\"task-example-badge\">ФИПИ</div><p><strong>Условие:</strong> Fe → FeCl₂ → Fe(OH)₂ → FeO (и ионное для 2-й реакции).</p><div class=\"task-example-solution\"><strong>Решение:</strong><p>1) Fe + 2HCl = FeCl₂ + H₂↑<br>2) FeCl₂ + 2NaOH = Fe(OH)₂↓ + 2NaCl; (Fe²⁺ + 2OH⁻ = Fe(OH)₂↓)<br>3) Fe(OH)₂ = FeO + H₂O (при t°).</p><div class=\"task-answer-box\">Ответ: <strong>4 балла</strong></div></div></div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Коэффициенты в сокращённом ионном</strong><p>Если в сокращённом ионном все коэффициенты делятся на 2 (например 2H⁺ + 2OH⁻ = 2H₂O), их ОБЯЗАТЕЛЬНО нужно сократить до H⁺ + OH⁻ = H₂O!</p></div>"}, {"num": "22", "shortTitle": "Задача на растворы", "part": "Часть 2", "title": "Задание № 22: Расчётная задача по уравнению реакции и раствору", "fipiSpec": {"number": "№ 22", "score": "3 балла", "time": "10–12 мин", "difficulty": "Повышенный", "docSource": "Кодификатор и открытый банк ФИПИ ОГЭ 2026/2027"}, "theory": "<h4>Универсальный алгоритм на 3 балла</h4>\n     <div class=\"task-formula-box\">\n       <div class=\"math-row\">1. Уравнение реакции с коэффициентами.<br>2. Масса чистого вещества в растворе: <strong>m<sub>чист</sub> = m<sub>р-ра</sub> · (w / 100)</strong>.<br>3. Количество вещества (моль): <strong>n = m / M</strong> (или для газа при н.у.: <strong>n = V / 22,4</strong>).<br>4. Переход по коэффициентам уравнения к искомому веществу и расчёт ответа!</div>\n     </div>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Пишите формулы и единицы измерения на каждом шаге:</strong> Молярную массу M находите в г/моль.</div></div></div>", "examples": "<div class=\"task-example-card\"><div class=\"task-example-badge\">ФИПИ</div><p><strong>Условие:</strong> К 100 г 10%-го раствора NaOH прилили избыток CuSO₄. Найдите массу осадка Cu(OH)₂.</p><div class=\"task-example-solution\"><strong>Решение:</strong><p>m(NaOH) = 10 г. n(NaOH) = 10 / 40 = 0,25 моль. По уравнению 2NaOH → 1Cu(OH)₂, значит n(Cu(OH)₂) = 0,125 моль. M(Cu(OH)₂) = 98 г/моль. m = 0,125 · 98 = 12,25 г.</p><div class=\"task-answer-box\">Ответ: <strong>12,25 г</strong></div></div></div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Подстановка массы раствора вместо чистого вещества</strong><p>В формулу n = m/M можно подставлять ТОЛЬКО массу чистого растворённого вещества!</p></div>"}, {"num": "23", "shortTitle": "Химический эксперимент", "part": "Часть 2 (Практика)", "title": "Задание № 23: Мысленный + реальный химический эксперимент с растворами", "fipiSpec": {"number": "№ 23", "score": "5 баллов (3 за №23 + 2 за №24)", "time": "20–25 мин", "difficulty": "Повышенный", "docSource": "Кодификатор и открытый банк ФИПИ ОГЭ 2026/2027"}, "theory": "<h4>Как получить все 5 баллов за №23 и №24</h4>\n     <p>В бланке №2 (задание 23) нужно написать <strong>2 уравнения реакций</strong>, доказывающих химические свойства выданного вещества, и указать <strong>признак каждой реакции</strong> (выпадение белого/голубого осадка, выделение газа, изменение окраски, растворение осадка). В задании 24 вы проводите эти 2 опыта на реальном столе перед экспертом!</p>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>В бланке запишите 2 уравнения и 2 признака:</strong> Выбирайте самые наглядные реакции (осадок или газ!).</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 2</div><div class=\"task-step-desc\"><strong>В №24 соблюдайте ТБ:</strong> Берите пробирку с этикеткой в сторону ладони, наливайте 1–2 мл, не касайтесь пипеткой стенок пробирки, закручивайте склянки своими крышками!</div></div></div>", "examples": "<div class=\"task-example-card\"><div class=\"task-example-badge\">ФИПИ</div><p><strong>Условие:</strong> Докажите свойства ZnSO₄, используя реактивы: NaOH, BaCl₂, HCl.</p><div class=\"task-example-solution\"><strong>Решение:</strong><p>1) ZnSO₄ + BaCl₂ = BaSO₄↓ + ZnCl₂ (выпадение белого осадка)<br>2) ZnSO₄ + 2NaOH = Zn(OH)₂↓ + Na₂SO₄ (выпадение белого студенистого осадка).</p><div class=\"task-answer-box\">Ответ: <strong>5 баллов</strong></div></div></div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Нарушение ТБ в №24</strong><p>Перепутали крышки от склянок или налили реактив мимо/с избытком → эксперт снимает баллы за технику безопасности!</p></div>"}];
